    "Reopen {agent}: its own models stay in {cmd}, and magpie's join them.": "重开 {agent} 后，{cmd} 中既有它自己的模型，也有 magpie 的模型。",
    "Once connected": "接入后",
    "Start it with": "启动命令",
    "View": "查看",
