    "Disconnect and restore": "断开并还原",
    "Changed ": "改动了 ",
    "Deleted": "删除",
    "Created": "新建",
    "value before connecting": "接入前的值",
    "Now: {line}": "现在：{line}",
    "{n} more lines": "还有 {n} 行",
    "{agent} goes back to how it was before it was connected; these are the places put back.": "{agent} 将恢复接入前的设置，以下为要改回的项。",
    "Reading what changes…": "正在读取要改回的地方…",
    "magpie's provider table stays, so sessions opened on magpie's models still open": "保留 magpie 供应商表，用 magpie 模型开过的会话还能打开",
    "Running {agent} copies take it once reopened": "正在运行的 {agent} 重开后生效",
    "Switch an agent on and the models you set up in magpie show up as the {magpie} provider in its own model list; or pick its model right here.": "打开「接入」后，magpie 中配置的模型会作为 {magpie} 供应商出现在 agent 的模型列表里；也可在此直接选模型。",
    "Pick a model": "选模型",
    "Pick one of magpie's models: {agent} is connected and starts on it": "选择 magpie 的模型：{agent} 自动接入并以它启动",
    "Its last pick": "上次的选择",
    "Unset, {agent} starts on its own last pick": "不设就用 {agent} 自己上次的选择",
    "Connected · starts on the model picked here": "已接入 · 用这里选的模型启动",
    "Let your agents use the models you set up in magpie": "让 agent 用上你在 magpie 里配的模型",
    "Switch an agent on and your models show up as the magpie provider in its own model list, to change in the agent. Or pick a model right here: the agent is connected and starts on it. Switch it off and it goes back to how it was.": "打开 agent 的「接入」，你的模型会作为 magpie 供应商出现在它的模型列表里，可在 agent 中切换。也可在此直接选模型：agent 自动接入并以它启动。关闭开关即恢复原状。",
    "Connected · pick magpie's models with {cmd} in {agent}": "已接入 · 在 {agent} 里用 {cmd} 选 magpie 的模型",
    "Connected · magpie's models are in {agent}'s model list": "已接入 · magpie 的模型在 {agent} 的模型列表里",
    "Connect {agent} to magpie": "将 {agent} 接入 magpie",
    "Add a provider or subscription in magpie first, then connect {agent}": "请先在 magpie 中添加一个供应商或订阅，再接入 {agent}",
    "Connected · switch off to put back what {agent} had before magpie": "已接入 · 关掉即还原 {agent} 接入 magpie 之前的设置",
    "Switch on and {agent}'s model list gets magpie's models": "打开后，{agent} 的模型列表里就有 magpie 的模型",
    "{agent} is connected to magpie": "{agent} 已接入 magpie",
    "{agent} is connected to magpie · back on {model}, what it was on when it was switched off": "{agent} 已接入 magpie · 回到上次断开前用的 {model}",
    "{agent} is connected to magpie · on {model} through magpie, the model it was on": "{agent} 已接入 magpie · 经 magpie 继续用它原来的模型 {model}",
    "{agent} is connected to magpie · on {model} through magpie: it had no model set, so the first of its own": "{agent} 已接入 magpie · 原先未设模型，改用它自己列表中的第一个：{model}",
    "{agent} is connected to magpie · on {model} through magpie: magpie doesn't serve the model it was on": "{agent} 已接入 magpie · magpie 没有它原来的模型，改用 {model}",
    "{agent} is connected to magpie · it stays on its own last pick; magpie's models join its {cmd}": "{agent} 已接入 magpie · 仍用它上次选的模型，magpie 的模型已加入 {cmd}",
    "via magpie": "经 magpie",
    "{agent} asks magpie for it": "{agent} 经 magpie 请求这个模型",
    "direct, not via magpie": "直连，不经 magpie",
    "off magpie": "不经 magpie",
    "{agent} as installed: magpie's endpoint and models come out": "{agent} 初始设置：移除 magpie 的地址和模型",
    "Take {agent} off magpie?": "让 {agent} 不再经过 magpie？",
    "Default is {agent} as installed: magpie's endpoint and models come out, and {agent} starts on its own default model. What it had before magpie isn't put back; Disconnect and restore does that.": "「默认」即 {agent} 的初始设置：移除 magpie 的地址和模型，{agent} 以自身默认模型启动。不还原接入前的设置，还原请用「断开并还原」。",
    "{model} is {agent}'s own model: {agent} asks {vendor} for it itself, with its own sign-in, not through magpie. Picking it takes {agent} off magpie, and it starts on {model}.": "{model} 是 {agent} 自带的模型：{agent} 用自己的登录直接向 {vendor} 请求，不经过 magpie。选择后 {agent} 断开 magpie，以 {model} 启动。",
    "「接入」 goes off, and {agent} is listed under Not set up with the agents not connected. Switch it on again to go back through magpie.": "「接入」将关闭，{agent} 列入「未设置」。再次打开「接入」即可重新经过 magpie。",
    "「接入」 goes off. Switch it on again to go back through magpie.": "「接入」将关闭，再次打开即可重新经过 magpie。",
    "Use default": "使用默认",
    "Use {model}": "使用 {model}",
    "{agent} no longer goes through magpie · on its own default": "{agent} 已不经过 magpie · 使用自身默认设置",
    "{agent} no longer goes through magpie; its own settings are back": "{agent} 已不再经过 magpie，原来的设置已还原",
    "Update to {v}": "更新到 {v}",
    "Updates with {cmd}": "通过 {cmd} 更新",
    "{agent} updated to {v}": "{agent} 已更新到 {v}",
