    "magpie's models join Codex's own; Codex stays signed in to ChatGPT, and while its account is used up magpie is Codex's provider, so the Codex app still sends": "默认。Codex 保持 ChatGPT 登录，magpie 的模型与 Codex 自带模型并列；账号额度用尽期间，magpie 临时作为 Codex 的供应商，让 Codex 应用仍能发送",
