    "Start magpie in the tray when you log in, so agents find the gateway from the start": "登录时在托盘启动 magpie，Agent 一开始就能连上网关",
    "move magpie to Applications first, then turn this on": "请先把 magpie 移到「应用程序」文件夹，再打开这个选项",
    "Keep magpie in the Dock too, always or while its window is open, for Cmd-Tab and a menu bar too full to show its icon": "程序坞中也显示 magpie（常驻或仅在窗口打开时），便于 Cmd-Tab 切换，菜单栏图标被挤掉时也能打开",
    "Lightweight mode": "轻量模式",
