    "Off": "关闭",
    "On": "开启",
    "Images": "图像",
    "Image recognition": "识图模型",
    "When the model in use can't see images, this one describes them to it, once for each image": "当前模型不能看图时，由此模型描述图片，每张图只描述一次",
    "A model that can't see images is sent none: a request with one in its latest message is turned away": "不给看不了图的模型发图片：最新一条消息带图的请求会被拒绝",
    "Automatic": "自动",
    "no model that sees": "没有能看图的模型",
    "images turned away": "带图的请求被拒绝",
    "Image generation": "生图模型",
    "The model Magpie Image draws with. Give an agent the tool from Library → MCP servers → Discover → Magpie Image; images are saved in its project": "Magpie Image 生图所用的模型。在 资源库 → MCP 服务器 → 发现 → Magpie Image 中把工具添加给 Agent，图片保存在其项目目录",
    "Agents given Magpie Image can't generate images or videos: the tool says it is off": "已装 Magpie Image 的 Agent 无法生成图片或视频，工具会提示已关闭",
    "no model that draws": "没有能生图的模型",
    "no images generated": "不生成图片",
    "Generate and edit images with the image model set in Magpie (Settings → Images), and make short videos with a Grok subscription, saved in the project.": "用 Magpie 设置的生图模型（设置 → 图像）生成和编辑图片，并可用 Grok 订阅生成短视频，保存在项目目录。",
    "Pick the agents that may generate images: each image costs what the model set in Settings → Images charges.": "选择可以生图的 Agent：每张图按 设置 → 图像 里所选模型的价格计费。",
