    "OTLP export": "OTLP 导出",
    "Collector connection": "采集服务连接",
    "Export scope": "导出范围",
    "Trace content": "链路内容",
    "Send traces to your collector. Choose what to include below; account credentials stay local": "向采集服务发送链路数据，在下方选择导出范围和内容；账号凭据留在本机",
    "Request and response content": "请求和响应内容",
    "Metadata only": "仅元数据",
    "Up to 256 KB": "最多 256 KB",
    "Full content": "完整内容",
    "Send model, token, status and timing metadata only. Prompts, replies and tool content stay local": "仅发送模型、Token、状态和耗时元数据；提示词、回复和工具内容留在本机",
    "Include requests and replies as trace input and output, with secrets masked. Each body is limited to 256 KB": "请求和回复作为链路的 Input 和 Output 发送，密钥脱敏；每份最多 256 KB",
    "Include complete requests and replies, with secrets masked. Large content may be refused by your collector": "包含完整的请求和回复，密钥会脱敏；内容过大时采集服务可能拒绝",
    "OTLP endpoint": "OTLP 端点",
    "Base URL of your collector, or Langfuse's /api/public/otel endpoint": "采集服务的基础地址，或 Langfuse 的 /api/public/otel 端点",
    "OTLP headers": "OTLP 请求头",
    "Comma-separated name=value pairs; percent-encode spaces and commas in values": "以逗号分隔的 name=value；值中的空格和逗号使用百分号编码",
    "Use comma-separated name=value headers": "请使用以逗号分隔的 name=value 请求头",
    "Export metrics": "导出指标",
    "Also send duration and token histograms. Leave off for a traces-only service such as Langfuse": "同时发送耗时和 Token 直方图；Langfuse 等仅接收链路的服务请保持关闭",
    "Trace agent conversations": "追踪代理对话",
    "Reads all local sessions from Codex, Pi, Oh My Pi, Claude Code, Cowork, OpenCode and Gemini CLI, including calls not routed through Magpie. When content is included below, exports prompts, replies, tool arguments and tool output (including file contents and command output), with secrets masked": "读取 Codex、Pi、Oh My Pi、Claude Code、Cowork、OpenCode 和 Gemini CLI 的全部本地会话，含未经 Magpie 的调用。若在下方选择包含内容，将导出提示词、回复、工具参数和工具输出（含文件内容和命令输出），并遮蔽敏感信息",
    "Environment variables override these saved OTLP preferences": "环境变量会覆盖这里保存的 OTLP 设置",
    "Privacy": "隐私",
    "Mask secrets": "脱敏密钥",
    "Local network": "局域网",
    "Share on local network": "局域网共享",
    "Gateway port": "网关端口",
    "Agents magpie connected move with it. Now {url}": "改了之后，已接入 magpie 的 Agent 会一起换过去。当前 {url}",
    "MAGPIE_ADDR={addr} sets the gateway’s address: unset it to set the port here": "MAGPIE_ADDR={addr} 已指定网关地址：去掉这个环境变量后才能在这里设端口",
    "A port is a number from 1024 to 65535": "端口是 1024 到 65535 之间的数字",
