    "Copied {label} address": "已复制 {label} 地址",
    "Agents on other computers on this network can use magpie’s models with a gateway key from Gateway": "同一网络中其他电脑上的 Agent 可凭网关页的网关密钥使用 magpie 的模型",
    "This computer has no local network address right now": "这台电脑现在没有局域网地址",
