    "The container’s own addresses, which other devices can’t reach: set MAGPIE_PUBLIC_URL to the host’s": "容器自身的地址，其他设备无法访问：请将 MAGPIE_PUBLIC_URL 设为宿主机地址",
    "New key": "换新 Key",
    "API keys, private keys, tokens and passwords go to vendors as placeholders, and come back as they were": "API Key、私钥、Token 和密码以占位符发给模型厂商，回复里再还原",
    "Mask personal data": "脱敏个人信息",
    "Count me as a user": "计入用户数",
    "Once a day, a random id for this computer with magpie's version and system — nothing you use magpie for": "每天一次，仅发送本机随机 ID、magpie 版本和系统，不含任何使用内容",
    "Warm-up and check-in": "预热与签到",
