    "Long conversations": "长对话",
    "Codex and Claude Code compact a conversation at 272K tokens, or the size typed here, on a model with a larger window, unless its provider has a Compact at of its own; in Claude Code a Claude model runs to its own window, 1M for a [1m] one, as Anthropic runs it. The model’s full window lets any conversation grow further, with every turn slower and costlier": "模型窗口超过 272K（或这里填的大小）时，Codex 和 Claude Code 在该处压缩对话，供应商设了自己的「压缩阈值」时以供应商的为准；Claude Code 中的 Claude 模型按自身窗口（[1m] 为 1M），与 Anthropic 官方一致。使用完整窗口可让对话更长，但每轮更慢、更贵",
