    "every {name} account needs signing in again. Sign one in under Providers, then move.": "所有 {name} 账号需重新登录。先在「供应商」中登录一个，再迁移。",
    "the plugin doesn't serve {models}. Untick them under Models, or keep the built-in.": "插件不提供 {models}。可在「模型」里取消勾选，或继续使用内置。",
    "the plugin doesn't serve {models} for {user}, though the built-in does. Untick them under Models, or keep the built-in.": "插件没有为 {user} 提供 {models}（内置提供）。可在「模型」里取消勾选，或继续使用内置。",
    "{user} doesn't work through the plugin: {error}": "{user} 无法通过插件使用：{error}",
    "{name} now runs on its plugin — {accounts}, {models}. Use the built-in again from here any time.": "{name} 已改由插件运行：{accounts}，{models}。可随时在此改回内置。",
    "{name} now runs on its plugin — {accounts}, {models}. Its editor in Providers moves it back.": "{name} 已改由插件运行：{accounts}，{models}。在「供应商」中编辑它即可改回。",
