    "Going back puts every account, with the plugin's newer sign-ins, back into the built-in.": "改回时，所有账号（连同插件里更新过的登录）都会回到内置。",
    "If an account doesn't work through the plugin, nothing changes.": "若有账号无法通过插件使用，则不做任何改动。",
