    "Routing": "路由",
    "Tick every key to use; Routing says how requests spread over them.": "勾选要使用的密钥；请求如何分配由「路由」决定。",
    "Runs through WSL · {distro}: Claude Code there signs in and answers; Windows has none of its own.": "经 WSL · {distro} 运行：Windows 上没有 Claude Code，登录和请求都由那里的 Claude Code 完成。",
    "Tick every account to use; Routing says how requests spread over them.": "勾选要使用的账号；请求如何分配由「路由」决定。",
    "Routing picks the account for each request through magpie; {agent} on its own uses the one it is signed in to, which magpie moves to the next ticked account with room once it is 98% used, and back to the first once that has room again.": "经 magpie 的请求由路由挑选账号；{agent} 直连时用它登录的账号，该账号用到 98% 时，magpie 把 {agent} 登录到下一个已勾选且有余量的账号，首选账号恢复后切回。",
    "Routing picks the account for each request through magpie; {agent} on its own uses the one it is signed in to, which magpie moves to the next ticked account with room once it is used up, and back to the first once that has room again.": "经 magpie 的请求由路由挑选账号；{agent} 直连时用它登录的账号，该账号额度用完时，magpie 把 {agent} 登录到下一个已勾选且有余量的账号，首选账号恢复后切回。",
    "Routing picks the account for each request through magpie; {agent} on its own stays signed in to the first account, whatever it has left.": "经 magpie 的请求由路由挑选账号；{agent} 直连时始终登录首选账号，无论剩余额度多少。",
