    "{agent} stays signed in to {user}": "{agent} 将始终登录 {user}",
    "{agent} is kept signed in to this account; requests through magpie go to the accounts in their order": "{agent} 始终登录这个账号；经过 magpie 的请求按账号顺序分配",
    "The gateway uses this account first; {agent} stays signed in to {user}": "网关优先使用这个账号；{agent} 仍登录 {user}",
    "Routing picks the account for each request through magpie, in the accounts' order; {agent} on its own stays signed in to {user}, whatever it has left.": "经 magpie 的请求由路由按账号顺序挑选；{agent} 直连时始终登录 {user}，无论剩余额度多少。",
    "magpie won't sign {agent} in to another account when the first runs low; requests through magpie still go to the other ticked accounts as Routing says": "首选账号额度快用完时，不会把 {agent} 登录到其他账号；经 magpie 的请求仍按「路由」分给其他已勾选账号",
    "{agent} stays signed in to the first account": "{agent} 将始终登录首选账号",
    "magpie moves {agent} to an account with room again": "首选账号额度不足时，会再把 {agent} 切到有余量的账号",
    "Smart": "智能",
    "The first takes requests while it has quota to spare; when it runs low, the one with the most left takes over. One out of credit sits out half an hour, one out of quota until it resets, one rate limited as long as the vendor asks, and one that fails a minute, longer each time it fails again.": "额度充足时请求都给第一个；快用完时由剩余最多的接手。欠费的暂停半小时，额度用完的暂停到重置，被限流的按厂商要求暂停，出错的暂停一分钟，再出错则逐次延长。",
    "In order": "按顺序",
    "In turn": "轮流",
    "Least used first": "用量少的优先",
    "By weight": "按权重",
    "By weight: it's {who}'s share \u2014 each key takes requests as its weight says.": "按权重：轮到 {who} 的份额——每个密钥按自己的权重接请求。",
    "Requests spread over the keys by the weight set beside each: a key weighing 3 takes three requests for every one a key weighing 1 takes, evenly over a few requests. One that fails is passed over while it rests, and the others share its requests; a conversation stays with its key as Stays says.": "请求按每个密钥旁设置的权重分配：权重 3 的密钥每接 3 个请求，权重 1 的接 1 个，几个请求之内就均匀分开。出错的在休息期间被跳过，由其他密钥按各自权重分担；会话按「会话保持」的设置留在原来的密钥上。",
    "Weight {n} · {share}%": "权重 {n} · {share}%",
    "Its share of the requests: a key weighing 3 takes three for every one a key weighing 1 takes": "它在请求中的份额：权重 3 的密钥每接 3 个请求，权重 1 的接 1 个",
    "{key} weighs {n}": "{key} 的权重已设为 {n}",
    "Requests go to the first; the next takes over when the one before runs out of quota, hits a rate limit or fails.": "请求先发给第一个；它额度用完、被限流或出错时，由下一个接手。",
    "Each turn of a conversation goes to the next one, spreading the load evenly; the requests within a turn stay where it began, so the prompt cache holds, and one that fails is passed over while it rests.": "会话每一轮轮流交给下一个，均摊负载；同一轮内的请求留在起始处，保持提示词缓存；出错的在暂停期间跳过。",
    "Each request goes to the one used least: a subscription by the share of its allowance used, a key by the tokens it served in the last hours.": "每个请求发给用量最少的：订阅看已用额度比例，密钥看最近几小时经它的 token 数。",
    "Weekly pace": "重置前用完",
    "Each request goes to the subscription with the most of its week left per hour until it renews — the one with the most to lose at its reset — so less of each week is lost at its reset; one at 90% or more waits until the others can't answer. A key goes by the tokens it served in the last hours.": "每个请求发给周剩余额度 ÷ 距重置小时数最高的订阅；用到 90% 以上的，等其他都无法响应时才用。密钥按最近几小时处理的 token 数排序。",
    "{name}: {routing}": "{name}：{routing}",
    "The gateway now uses {user} first": "网关现在优先使用 {user}",
    "{agent} signs in to the first. Tick more and the gateway moves on to the next when the one before it is out of quota. Sessions already running keep theirs until restarted.": "{agent} 登录首选账号；勾选多个时，前一个额度用完网关自动换下一个。已在运行的会话保持原账号，重启后切换。",
    "{agent} is signed in to this account": "{agent} 当前登录的就是这个账号",
    "Stop using this account": "停用这个账号",
