    "Sign in with ChatGPT: your plan on OpenAI's own API, with your agent's own instructions rather than Codex's.": "用 ChatGPT 登录（Sign in with ChatGPT）：通过 OpenAI 官方 API 使用你的套餐，用的是你 agent 自己的指令，而不是 Codex 的。",
