    "{name} is used through its own CLI, which isn't on this computer yet. magpie is installing it with the official installer; the sign-in page opens as soon as it's done.": "{name} 需通过自身 CLI 使用，本机尚未安装。正在用官方安装脚本安装，完成后立即打开登录页。",
