    "If the page the browser ends on won't load (magpie runs on a server or in Docker), copy its whole address and paste it here.": "若浏览器最终停在打不开的页面（magpie 运行在服务器或 Docker 中），请复制其完整地址粘贴到这里。",
    "Callback URL": "回调 URL",
    "If the page can't reach magpie (it runs on a server or in Docker), make an API key on {name}'s keys page and paste it here.": "若页面连不上 magpie（运行在服务器或 Docker 中），请在 {name} 的密钥页创建 API 密钥并粘贴到这里。",
    "Open the keys page": "打开密钥页面",
