    "Signing in on {host}": "正在 {host} 登录",
    "An account of an enterprise on GitHub Enterprise Cloud with data residency signs in at its <name>.ghe.com": "使用数据驻留的 GitHub Enterprise Cloud 企业账号，要在企业自己的 <name>.ghe.com 登录",
    "Your enterprise on GHE.com": "你的企业在 GHE.com 上的地址",
    "The address you sign in to GitHub at, like acme.ghe.com. An account on github.com doesn't need it.": "登录 GitHub 的地址，例如 acme.ghe.com。github.com 账号无需填写。",
    "Type your enterprise's <name>.ghe.com": "请输入企业的 <name>.ghe.com 地址",
    "magpie opened Factory's sign-in page. Check it shows this code and confirm it; the account shows up here as soon as you're done.": "已打开 Factory 登录页，请核对页面显示的验证码与下方一致后确认；完成后账号会出现在这里。",
    "Droid Core · 5 hours": "Droid Core · 5 小时",
