    "Paste one or more Factory API keys (fk-…, from app.factory.ai/settings/api-keys), one a line, or choose a file with them. Each key is checked with Factory before it is added.": "粘贴一个或多个 Factory API Key（fk-…，在 app.factory.ai/settings/api-keys 创建），每行一个，或选择包含它们的文件。每个 Key 先经 Factory 校验再添加。",
