    "Choose or paste an export from Antigravity Cockpit, Antigravity Manager or CLIProxyAPI — JSON, or refresh tokens one a line. Each account is checked with Google before it is added.": "选择或粘贴 Antigravity Cockpit、Antigravity Manager 或 CLIProxyAPI 的导出内容：JSON，或每行一个 refresh token。每个账号先经 Google 验证再添加。",
