    "Choose or paste CLIProxyAPI's auth files (JSON) or {own}. Each account's sign-in is refreshed with {vendor} before it is added.": "选择或粘贴 CLIProxyAPI 的认证文件（JSON）或 {own}。每个账号先向 {vendor} 刷新登录再添加。",
    "Refreshing it spends the file's sign-in: the tool it came from will need to sign in again to use that account.": "刷新会使文件中的登录失效：原工具需重新登录才能继续使用该账号。",
