    "Restart it to use the new account. Running Codex sessions will be interrupted.": "重启后才会使用新账号，正在运行的 Codex 会话将中断。",
    "Restart Zed if it still asks for an API key: magpie has configured its gateway credential in the system credential store.": "若 Zed 仍要求输入 API 密钥，请重启 Zed：网关凭据已写入系统凭据存储。",
    "In Air, start a new task and pick Magpie in its agent menu: magpie's models and routing groups are in its model menu.": "在 Air 中新建任务并在智能体菜单选 Magpie：模型菜单中即有 magpie 的模型和路由组。",
    "Air runs magpie's models through OpenCode's ACP server, and OpenCode isn't installed here: install OpenCode (npm i -g opencode-ai), then pick Magpie in a new Air task.": "Air 经 OpenCode 的 ACP 服务使用 magpie 的模型，本机未安装 OpenCode：请先安装（npm i -g opencode-ai），再在 Air 新任务中选 Magpie。",
    "magpie's models are in VS Code's Chat model picker, under magpie (VS Code 1.122 or later). If they don't show, run Developer: Reload Window in VS Code.": "magpie 的模型位于 VS Code 聊天模型选择器的 magpie 分组下（需 VS Code 1.122 或更高）。若未出现，请在 VS Code 中运行 Developer: Reload Window。",
