    "The library checks skills for updates with it: GitHub allows 5,000 requests an hour with a token, 60 without. It needs no scopes.": "资源库检查技能更新时使用。GitHub 每小时允许带令牌 5000 次请求，不带仅 60 次。无需勾选权限。",
    "Using {env} from the environment ({mask}); a token set here comes first.": "正在使用环境变量 {env}（{mask}）；在这里设置的令牌优先。",
    "a GitHub token is one word, without spaces": "GitHub 令牌是一串不含空格的字符",
    "GitHub's rate limit for your GitHub token is used up until {time}": "你的 GitHub 令牌的请求额度已用完，{time} 恢复",
    "GitHub's rate limit for your GitHub token is used up for now": "你的 GitHub 令牌的请求额度暂时用完了",
    "GitHub allows 60 requests an hour without a token, used up until {time}. Add a GitHub token in Settings → Network and sharing to raise it to 5,000.": "GitHub 不带令牌每小时仅允许 60 次请求，已用完，{time} 恢复。在 设置 → 网络与共享 添加 GitHub 令牌可提高到 5000 次。",
    "GitHub allows 60 requests an hour without a token, used up for now. Add a GitHub token in Settings → Network and sharing to raise it to 5,000.": "GitHub 不带令牌每小时仅允许 60 次请求，暂时已用完。在 设置 → 网络与共享 添加 GitHub 令牌可提高到 5000 次。",
    "GitHub refused the GitHub token in Settings → Network and sharing: it may have expired or been revoked": "GitHub 拒绝了 设置 → 网络与共享 中的 GitHub 令牌：它可能已过期或被撤销",
