    "Use one…": "用一张…",
    "Use a reset": "用一张重置卡",
    "Its week was used up, so one of {account}'s Codex resets was used by itself first.": "本周额度已用完，已先自动使用 {account} 的一张 Codex 重置卡。",
  "{who} answered {status}: its week is used up and nobody else could take the request, so one of {account}'s Codex resets was used by itself and the request is asked again, before any of the reply reaches {agent}.": "{who} 返回 {status}：本周额度已用完且无其他账号可接手，已自动使用 {account} 的一张 Codex 重置卡并重发请求，{agent} 尚未收到任何回复。",
    "{who} no longer uses a reset by itself": "{who} 不再自动使用重置卡",
    "Auto-use resets": "自动使用重置卡",
    "Auto-use resets:": "自动使用重置卡：",
    "when the week runs out, or before one expires": "周额度用完时 · 重置卡到期前",
    "Auto-use": "自动用卡",
    "Auto-use: on": "自动用卡：开",
    "Auto-use: off": "自动用卡：关",
    "auto-used before it expires": "到期前自动使用",
    "not auto-used": "不会自动使用",
    "Auto-use is on: the reset that runs out first is used about half an hour before it does, if this account's windows have been used, so what they have left can be used until then and it isn't lost; at once if the account is held up until after then.": "自动使用已开启：最早到期的重置卡在到期前约半小时自动使用（需账号已用过额度），之前仍可用完剩余额度，卡也不会作废；若限流到那之后才解除，则立即使用。",
    "Auto-use is off: the reset that runs out first is lost unless it's used by hand before then.": "自动使用已关闭：最早到期的重置卡若未在到期前手动使用，将作废。",
    "On: a reset is used by itself when this account's week is used up and no other account can answer, one a week at most, and the one about to run out is used about half an hour before it does, if the account has been used, or at once when the account is held up until after then. Otherwise the five hours running out never uses one. Click to turn it off.": "已开启：周额度用完且无其他账号可接手时自动用一张重置卡，每周最多一张；快到期的卡在到期前约半小时自动使用（需账号已用过额度；若限流到那之后才解除，则立即使用）。仅 5 小时额度用完不会动用重置卡。点击关闭。",
    "Off: this account's resets are used only by hand. Turned on, one is used by itself when its week is used up and no other account can answer, one a week at most, and the one about to run out about half an hour before it does, if the account has been used, or at once when the account is held up until after then. Otherwise the five hours running out never uses one.": "已关闭：重置卡仅手动使用。开启后，周额度用完且无其他账号可接手时自动用一张，每周最多一张；快到期的卡在到期前约半小时自动使用（需账号已用过额度；若限流到那之后才解除，则立即使用）。仅 5 小时额度用完不会动用重置卡。",
    "{who} uses a reset by itself when its week runs out, or before one expires": "{who} 会在周额度用完时、或重置卡到期前自动使用重置卡",
    "Uses the reset that runs out first ({when}), never one that lasts longer.": "使用最早到期的一张（{when} 到期），不会先用有效期更长的。",
    "Uses one of its resets; none of them runs out.": "使用一张重置卡；这些重置卡均不会过期。",
    "This account's windows start again at once, as if none had been used. You're asked before anything is spent.": "使用后此账号的额度窗口立即重新开始，如同未曾使用。使用前会先确认。",
    "The one used is the one that runs out first, {when}.": "使用最早到期的一张（{when} 到期）。",
    "Use a Codex reset?": "用一张 Codex 重置卡？",
    "nothing to reset — no window is used up yet, and the reset is kept": "不必使用：尚无额度窗口用完，重置卡保留",
    "a reset was used a short while ago — try again later": "刚刚用过一张重置卡，请稍后再试",
    "the account can't use a reset": "这个账号不能使用重置卡",
    "resets can't be used right now — try again later": "现在无法使用重置卡，请稍后再试",
    "{who} has 1 reset. Using it starts its windows again at once, as if none of them had been used. It can't be undone.": "{who} 有 1 张重置卡。使用后其额度窗口立即重新开始，如同未曾使用。此操作无法撤销。",
    "{who} has {n} resets. Using one starts its windows again at once, as if none of them had been used. It can't be undone.": "{who} 有 {n} 张重置卡。使用一张后其额度窗口立即重新开始，如同未曾使用。此操作无法撤销。",
    "None of its windows has been used yet, so there is nothing to start again.": "额度窗口尚未使用，现在重置没有效果。",
    "1 window started again": "1 个额度窗口已重新开始",
    "{n} windows started again": "{n} 个额度窗口已重新开始",
    "nothing to start again — no window has been used, and the reset is kept": "不必使用：额度窗口都还没用过，重置卡保留",
    "no reset left on the account": "这个账号已没有重置卡",
    "that reset was already used": "这张重置卡已经用过了",
    "Allowances": "额度",
    "What is left on the account: the vendor tells only this, so Used / Left leaves it as it is": "账户余额：供应商只提供此数，不受「已用 / 剩余」切换影响",
    "What is left on the account besides its windows": "账户里除周期额度外的其他余额或积分",
    "Headers": "请求头",
    "Sign-in": "登录",
    "For a server that asks you to sign in (OAuth): magpie signs in once, and every agent given it uses that sign-in": "用于需要登录（OAuth）的服务器：在 magpie 登录一次，分配到它的 agent 共用此登录",
    "Opening the sign-in…": "正在打开登录…",
    "this server already works without signing in, so there is nothing to sign in to: the agents given it can use it as it is. A key it takes goes in Headers; a server that signs in at another address (as Exa's ?login) needs that URL": "此服务器无需登录即可使用，分配到它的 agent 可直接使用。所需密钥填在请求头中；需在另一地址登录的服务器（如 Exa 的 ?login）请填该 URL",
    "Finish signing in in your browser…": "请在浏览器中完成登录…",
