    "Signed out of {name} — the agents are given the server's own address again": "已退出 {name}，agent 改回使用服务器自身的地址",
    "Extra HTTP headers sent to the vendor, applied after auth. For gateways that need a private scheme.": "发给供应商的额外 HTTP 请求头，在鉴权后应用，用于需要私有鉴权方案的网关。",
