    "How many requests may wait for each key or account; one more is turned away at once. 0 or empty is no bound": "每个 Key 或账号最多可排队的请求数，再多的请求会立刻被拒绝。0 或留空为不限",
    "Seconds a request waits for a free slot before it is turned away. 0 or empty waits as long as it takes": "请求等待空位的最长秒数，超时即被拒绝。0 或留空为一直等",
