    "optional · only for a team plan": "可选 · 仅团队套餐需要",
    "Only for a key on a team's GLM Coding Plan: both are in {p}'s console, under the team's organization and project. With them the Usage page shows the team's 5-hour and weekly windows.": "仅团队 GLM Coding Plan 的 Key 需要：两者见 {p} 控制台的团队组织与项目。填写后用量页显示团队的 5 小时与每周额度。",
    "Team plan: give both the organization ID and the project ID": "团队套餐：请同时填写组织 ID 和项目 ID",
    "A key tells only the balance. The Step Plan's 5-hour, weekly and credit windows are told only to a StepFun sign-in: bring yours here once and magpie keeps it (for 30 days), used for nothing else.": "API Key 只能查余额。Step Plan 的 5 小时、每周和积分额度仅对 StepFun 网页登录开放：导入一次登录，magpie 保存 30 天，仅用于查询额度。",
