    "What the Balance URL is asked with in place of the key, when it wants the account's own token: a new-api relay's System Access Token, or a sub2api panel's login token (a JWT, sent as a Bearer); it is used for nothing else.": "余额接口需要账户自己的令牌时，用它代替 Key 去请求：new-api 中转站填「系统访问令牌」，sub2api 面板填登录令牌（JWT，会以 Bearer 发送）；不作他用。",
    "…/api/usage/token takes the API key, not this token: a new-api relay tells the account's balance to the token at /api/user/self.": "…/api/usage/token 只认 API Key，不认这个令牌：new-api 中转站用 /api/user/self 凭令牌查账户余额。",
    "The token needs a Balance URL: a new-api relay tells the account's balance to it at /api/user/self.": "令牌还需要一个余额查询地址：new-api 中转站用 /api/user/self 凭令牌查账户余额。",
