    "the last {n} the gateway keeps": "网关保留的最近 {n} 个",
    "Accounts and keys": "账号与密钥",
    "over those requests": "统计自这些请求",
    "Nothing on {day}": "{day}没有请求",
    "No requests since magpie started": "magpie 启动以来还没有请求",
    "Each request an agent sends through magpie shows up here: who answered it, why, and each try.": "agent 经 magpie 发出的每个请求都列在这里：由谁应答、为何选它，以及每次尝试。",
    "Earlier ones are kept by day, in the bar above.": "更早的请求按天保存，在上面的日期里查看。",
