    "{who} is left out: the gateway key asking may not use its account.": "{who} 被排除：发起请求的网关密钥不能使用它的账号。",
    "{who} is left out: a usage window is at {n}, past the {cap}% cap set on the account, so it counts as used up until that window renews.": "{who} 不参与：某个用量窗口已用 {n}，超过该账号的 {cap}% 上限，窗口重置前视为已用完。",
    "No cap": "不设上限",
    "Cap {n}%": "上限 {n}%",
    "Usage cap": "用量上限",
