    "answered {agent}": "回答了 {agent}",
    "routing group": "路由组",
    "Routing groups": "路由组",
    "{n} agents at once": "{n} 个 Agent 同时在发",
    "In order: member by member, the first model the group names until it can't answer, each over its own accounts or keys as its provider routes them.": "按顺序：逐个成员，先用组内第一个模型，无法响应再换下一个；各成员按其供应商的路由在自己的账号或 Key 间分配。",
    "{agent} asked for the routing group {name}: {members}": "{agent} 请求了路由组 {name}：{members}",
    "Kept on {who}: it answered this conversation before, and affinity keeps a session with one account.": "留在 {who}：此会话之前由它回答，亲和性使会话保持同一账号。",
    "Kept on {who}: {agent} is handing back tool results within turn {n}, and moving now would lose what the vendor cached of it.": "留在 {who}：{agent} 正在第 {n} 轮内回传工具结果，此时换账号会丢掉厂商为它缓存的内容。",
    "Kept on {who}: the vendor read {n} tokens of this conversation from its cache {d} ago; anyone else would be sent them afresh and paid in full.": "留在 {who}：{d}前厂商从缓存读取了此会话的 {n} tokens；换账号需重新发送并全价计费。",
    "Turn {n} begins: in turn, it goes to the one after {who}, which answered the last turn — {next}.": "第 {n} 轮开始：轮流交给上一轮回答者 {who} 的下一个，即 {next}。",
    "Turn {n} begins: affinity keeps a conversation only within a turn, so routing decides afresh.": "第 {n} 轮开始：亲和性仅在一轮内保持，路由重新决定。",
    "{who} answered this conversation last, but it is resting, so the conversation moves.": "此会话上次由 {who} 回答，但它在休息，已换账号。",
    "{who} answered this conversation last, but its allowance is all but used up, so the conversation moves.": "此会话上次由 {who} 回答，但其额度将尽，已换账号。",
    "{who} answered this conversation last, but it is no longer one to route to.": "此会话上次由 {who} 回答，但它已不可路由。",
    "{who} answered this conversation last, but the vendor read only {n} tokens of it from its cache then — not worth staying for.": "此会话上次由 {who} 回答，但当时厂商只从缓存读取了 {n} tokens，不值得保留。",
    "{who} answered this conversation {d} ago, longer than the 5 minutes a vendor keeps a prompt cached — so routing decides afresh.": "此会话 {d}前由 {who} 回答，已超过厂商缓存提示词的 5 分钟，路由重新决定。",
    "Affinity is off: each request is routed afresh, whoever answered its conversation before.": "亲和性已关闭：每个请求都重新路由，不论之前由谁回答。",
