    "Let your agents use the models you set up in magpie": "magpie で設定したモデルをエージェントで使う",
    "Switch an agent on and your models show up as the magpie provider in its own model list, to change in the agent. Or pick a model right here: the agent is connected and starts on it. Switch it off and it goes back to how it was.": "エージェントをオンにすると、モデルがそのエージェント自身のモデル一覧に magpie プロバイダとして表示され、エージェント内で切り替えられます。ここでモデルを直接選ぶこともでき、その場合エージェントは接続されてそのモデルで起動します。オフにすると元の状態に戻ります。",
