    "{agent} is connected to magpie · on {model} through magpie: it had no model set, so the first of its own": "{agent} は magpie に接続されています · モデルが未設定だったため、独自のモデルの最初の {model} を magpie 経由で使用",
    "{agent} is connected to magpie · on {model} through magpie: magpie doesn't serve the model it was on": "{agent} は magpie に接続されています · 使っていたモデルを magpie が提供していないため、{model} を magpie 経由で使用",
    "{agent} is connected to magpie · it stays on its own last pick; magpie's models join its {cmd}": "{agent} は magpie に接続されています · モデルは前回自分で選んだもののままで、magpie のモデルが {cmd} に加わります",
