    "CLI not found": "CLI が見つかりません",
    "{agent}'s settings are still here ({path}), but its command-line program isn't found: it may have been uninstalled. Install another agent, below the list, has its install command.": "{agent} の設定は残っています（{path}）が、コマンドラインプログラムが見つかりません。アンインストールされた可能性があります。リストの下の「他のエージェントをインストール」にインストールコマンドがあります。",
    "{agent}'s settings are still here, but its command-line program isn't found": "{agent} の設定は残っていますが、コマンドラインプログラムが見つかりません",
    "Run a command in a terminal, then come back: magpie lists the agent here once it is installed. The npm commands need Node.js (nodejs.org).": "ターミナルでコマンドを実行してから戻ってください。インストールされると magpie がここにエージェントを表示します。npm コマンドには Node.js（nodejs.org）が必要です。",
    "Run a command in a terminal, then come back: magpie lists the agent here once it is installed.": "ターミナルでコマンドを実行してから戻ってください。インストールされると magpie がここにエージェントを表示します。",
    "No Node.js was found here, so the npm commands install it with nvm first.": "Node.js が見つからないため、npm コマンドはまず nvm で Node.js をインストールします。",
    "On a Mac, nvm needs Xcode's Command Line Tools: if it asks for them, run xcode-select --install, then the command again.": "Mac では nvm に Xcode のコマンドラインツールが必要です。求められたら xcode-select --install を実行し、もう一度コマンドを実行してください。",
    "No Node.js was found here, so the npm commands install it with winget first; run them in PowerShell. If npm isn't found after Node.js is installed, open a new terminal and run the npm install again.": "Node.js が見つからないため、npm コマンドはまず winget で Node.js をインストールします。PowerShell で実行してください。Node.js のインストール後に npm が見つからない場合は、新しいターミナルを開いて npm install をもう一度実行してください。",
