    "an open Claude Code session keeps the effort it started with — restart it to use this.": "開いている Claude Code セッションは起動時の推論レベルのままです。反映するには再起動してください。",
    "an open Claude Code session keeps the ultracode it started with — restart it to use this.": "開いている Claude Code セッションは起動時の ultracode のままです。反映するには再起動してください。",
    "magpie's models join Codex's own; Codex stays signed in to ChatGPT, and while its account is used up magpie is Codex's provider, so the Codex app still sends": "magpie のモデルが Codex 独自のモデルに加わります。Codex は ChatGPT にサインインしたままで、アカウントの使用量を使い切っている間は magpie が Codex のプロバイダーになり、Codex アプリは送信を続けられます",
    "Always ChatGPT": "常に ChatGPT",
    "as ChatGPT, and kept so when its account is used up: magpie never becomes Codex's provider. The Codex app may then send nothing till the account has room; Codex CLI goes on through magpie": "ChatGPT と同じで、アカウントの使用量を使い切っても切り替えません。magpie が Codex のプロバイダーになることはありません。その間 Codex アプリはアカウントに余裕が戻るまで送信できないことがあります。Codex CLI は magpie 経由で続行します",
    "magpie is Codex's provider; the Codex app is in its API state, with magpie's models only": "magpie が Codex のプロバイダになります。Codex アプリは API 状態になり、magpie のモデルのみが表示されます",
