    "Image generation": "画像生成",
    "The model Magpie Image draws with. Give an agent the tool from Library → MCP servers → Discover → Magpie Image; images are saved in its project": "Magpie Image が画像生成に使うモデルです。ライブラリ → MCP サーバー → 発見 → Magpie Image からエージェントにツールを付与してください。画像はそのプロジェクトに保存されます",
    "Agents given Magpie Image can't generate images or videos: the tool says it is off": "Magpie Image を付与されたエージェントは画像や動画を生成できません：ツールがオフであることを伝えます",
