    "Generate and edit images with the image model set in Magpie (Settings → Images), and make short videos with a Grok subscription, saved in the project.": "Magpie で設定した画像モデル（設定 → 画像）で画像を生成・編集し、Grok サブスクリプションで短い動画を作成します。プロジェクトに保存されます。",
    "Pick the agents that may generate images: each image costs what the model set in Settings → Images charges.": "画像を生成できるエージェントを選んでください：画像 1 枚ごとに、設定 → 画像 で選んだモデルの料金がかかります。",
    "Observability": "オブザーバビリティ",
    "OTLP export": "OTLP エクスポート",
