    "Send model, token, status and timing metadata only. Prompts, replies and tool content stay local": "モデル、トークン、ステータス、所要時間のメタデータのみを送信します。プロンプト、返信、ツールの内容はローカルに残ります",
    "Include requests and replies as trace input and output, with secrets masked. Each body is limited to 256 KB": "リクエストと返信をトレースの入力と出力として含めます（シークレットはマスク）。各本文は 256 KB まで",
