    "Trace agent conversations": "エージェントの会話をトレース",
    "Reads all local sessions from Codex, Pi, Oh My Pi, Claude Code, Cowork, OpenCode and Gemini CLI, including calls not routed through Magpie. When content is included below, exports prompts, replies, tool arguments and tool output (including file contents and command output), with secrets masked": "Codex、Pi、Oh My Pi、Claude Code、Cowork、OpenCode、Gemini CLI のすべてのローカルセッションを読み取ります（Magpie を経由しない呼び出しも含む）。下で内容を含めると、プロンプト、返信、ツールの引数と出力（ファイル内容やコマンド出力を含む）をシークレットをマスクしてエクスポートします",
    "Environment variables override these saved OTLP preferences": "環境変数は、ここに保存された OTLP の設定より優先されます",
