    "Whether “· routing group” follows a group’s name in the agents’ lists: one setting for every group, and for the provider after each model’s name, as on Settings.": "エージェントの一覧でグループ名の後に「· routing group」を付けるかどうか。すべてのグループに共通の設定で、モデル名の後のプロバイダ名にも効きます（「設定」と同じものです）。",
    "“· routing group” is set for every group above": "「· routing group」を付けるかは上で全グループ共通に設定します",
    "Codex subagents on any model": "Codex のサブエージェントで任意のモデル",
    "Long conversations": "長い会話",
    "Codex and Claude Code compact a conversation at 272K tokens, or the size typed here, on a model with a larger window, unless its provider has a Compact at of its own; in Claude Code a Claude model runs to its own window, 1M for a [1m] one, as Anthropic runs it. The model’s full window lets any conversation grow further, with every turn slower and costlier": "ウィンドウが大きいモデルでは、Codex と Claude Code は 272K トークン（またはここに入力したサイズ）で会話を圧縮します。プロバイダーに独自の「圧縮しきい値」があればそちらが優先されます。Claude Code の Claude モデルは Anthropic と同じく自身のウィンドウ（[1m] なら 1M）まで使います。モデルのウィンドウ全体を使うとどの会話もさらに伸ばせますが、ターンごとに遅く、高くなります",
