    "as Codex picks it": "Codex の既定どおり",
    "Codex’s auto-review decides approvals on this model, whatever model the conversation is on": "Codex の自動レビュー（auto-review）は、会話のモデルにかかわらずこのモデルで承認を判断します",
    "Codex’s auto-review decides approvals on codex-auto-review when it has it, else on the conversation’s model at low effort": "Codex の自動レビュー（auto-review）は codex-auto-review があればそれで、なければ会話のモデル（low の推論）で承認を判断します",
    "no title, nothing sent": "タイトルなし、送信なし",
    "Codex asks its own model for each thread’s title through its ChatGPT sign-in, even while the conversation is on magpie’s models": "会話が magpie のモデルで行われていても、Codex は ChatGPT のサインインを通じて自身のモデルに各スレッドのタイトルを生成させます",
    "Codex’s title requests are answered by magpie with no title and sent nowhere; new threads stay unnamed": "Codex のタイトルリクエストには magpie がタイトルなしで応答し、どこにも送りません。新しいスレッドは無題のままです",
    "Codex’s title requests go to this model, not to its ChatGPT sign-in; the Usage and Routing views still show them as titles": "Codex のタイトルリクエストは ChatGPT のサインインではなくこのモデルに送られます。使用量とルーティングの画面では引き続きタイトルとして表示されます",
    "Codex’s OpenAI models hand subagents their tasks as text (multi-agent V1), so a GPT lead can spawn them on magpie’s other models. New threads only; Codex’s own multi_agent_v2 setting still wins": "Codex の OpenAI モデルはサブエージェントにタスクをテキストで渡す（multi-agent V1）ため、GPT のリードが magpie の他のモデルでサブエージェントを起動できます。新しいスレッドのみ対象です。Codex 自身の multi_agent_v2 設定が優先されます",
