    "One tiny request starts the next window at once": "ごく小さなリクエストを 1 件送り、次の期間をすぐに開始します",
    "One tiny request through Claude Code (Haiku) starts the next window at once": "Claude Code（Haiku）経由でごく小さなリクエストを 1 件送り、次の期間をすぐに開始します",
    "Starts each account's 5-hour window at this time every day": "毎日この時刻に各アカウントの 5 時間枠を開始します",
