    "On this machine": "このマシン上",
    "Custom": "カスタム",
    "Nothing called “{q}”. ": "「{q}」というものはありません。",
    "Add it as a custom provider": "カスタムプロバイダとして追加",
    "{name} is already added — open it": "{name} は追加済みです — 開く",
    "Chat Completions — most agents": "Chat Completions — ほとんどのエージェント",
    "OpenAI Responses — what Codex speaks": "OpenAI Responses — Codex が使う形式",
    "Anthropic Messages — what Claude Code speaks": "Anthropic Messages — Claude Code が使う形式",
