    "{agent} is on {model} — click to change": "{agent} は {model} を使用中 — クリックして変更",
    "{agent} is on the routing group {group}, {model} here among its members — click to change": "{agent} はルーティンググループ {group} を使用中で、ここの {model} はそのメンバーです — クリックして変更",
    "e.g. My Relay": "例：My Relay",
    "Name": "名前",
    "OpenAI compatible": "OpenAI 互換",
    "…/v1 — chat completions, and responses when the vendor has it": "…/v1 — chat completions、ベンダーが対応していれば responses も",
    "OpenAI Responses": "OpenAI Responses",
    "…/v1 — for a vendor that serves only the Responses API, not chat completions": "…/v1 — chat completions ではなく Responses API のみを提供するベンダー向け",
    "Anthropic compatible": "Anthropic 互換",
