    "Sign-in": "サインイン",
    "For a server that asks you to sign in (OAuth): magpie signs in once, and every agent given it uses that sign-in": "サインインを求めるサーバー（OAuth）向け：magpie で一度サインインすれば、割り当てられたすべてのエージェントがそのサインインを使います",
    "Opening the sign-in…": "サインインを開いています…",
    "this server already works without signing in, so there is nothing to sign in to: the agents given it can use it as it is. A key it takes goes in Headers; a server that signs in at another address (as Exa's ?login) needs that URL": "このサーバーはサインインなしで既に使えるため、サインインする対象がありません。割り当てられたエージェントはそのまま使えます。必要なキーはヘッダーに入れてください。別のアドレスでサインインするサーバー（Exa の ?login など）はその URL が必要です",
    "Finish signing in in your browser…": "ブラウザでサインインを完了してください…",
