    "its sign-in is gone; sign in again": "サインイン情報がありません。再度サインインしてください",
    "Claude Code could not authenticate this account; sign in again in magpie": "Claude Code はこのアカウントを認証できませんでした。magpie で再度サインインしてください",
    "Tested {user}: {result}": "{user} をテストしました：{result}",
    "{who} could not authenticate. Sign in again in magpie; this login is not retried. The request went to {next}.": "{who} は認証できませんでした。magpie で再度サインインしてください。このログインは再試行されません。リクエストは {next} に送られました。",
    "{who} could not authenticate. Sign in again in magpie; this login is not retried. No other account could answer.": "{who} は認証できませんでした。magpie で再度サインインしてください。このログインは再試行されません。応答できる他のアカウントはありませんでした。",
    "Open it to sign in again": "開いて再度サインイン",
    "Signed in to {name} — the agents given it use magpie's sign-in": "{name} にサインインしました。割り当てられたエージェントは magpie のサインインを使います",
    "Signed out of {name} — the agents are given the server's own address again": "{name} からサインアウトしました。エージェントには再びサーバー自身のアドレスが渡されます",
    "Extra HTTP headers sent to the vendor, applied after auth. For gateways that need a private scheme.": "認証の後に適用される、ベンダーに送る追加の HTTP ヘッダー。独自の方式が必要なゲートウェイ向けです。",
