    "Requests to it go through this proxy: http://, https:// or socks5://": "このプロバイダへのリクエストはこのプロキシを経由します：http://、https://、socks5://",
    "Proxy: type its address, like http://127.0.0.1:7890": "プロキシ：アドレスを入力してください（例：http://127.0.0.1:7890）",
    "Provider's proxy": "プロバイダのプロキシ",
    "Each account can go through a proxy of its own; Provider's proxy is the one above": "アカウントごとに専用のプロキシを経由できます。「プロバイダのプロキシ」は上の項目です",
    "Proxy of {user}: type its address, like http://127.0.0.1:7890": "{user} のプロキシ：アドレスを入力してください（例：http://127.0.0.1:7890）",
    "Concurrency": "同時実行数",
