    "As long as it takes": "いつまでも",
    "Queue size": "キューの長さ",
    "Queue wait": "キューの待ち時間",
    "How many requests may wait for each key or account; one more is turned away at once. 0 or empty is no bound": "キーまたはアカウントごとに待てるリクエスト数。超えた分はすぐ断られます。0 または空欄で上限なし",
    "Seconds a request waits for a free slot before it is turned away. 0 or empty waits as long as it takes": "空きを待つ最大秒数。過ぎると断られます。0 または空欄でいつまでも待ちます",
    "Queue size: a whole number from 0 to 10000": "キューの長さ：0〜10000 の整数",
