    "the provider's": "プロバイダーの設定",
    "At most {n} requests out at once on this one, {whose}; more wait in a queue and go in order. Counted across every model, routing group and agent": "この項目で同時に送るリクエストは最大 {n} 件（{whose}）。超えた分は順番に待ちます。すべてのモデル・ルーティンググループ・エージェントで共有されます",
    "No limit on requests at once on this one, {whose}": "この項目の同時リクエスト数は無制限（{whose}）",
