    "No limit": "上限なし",
    "Price rate": "価格倍率",
    "1, the official price": "1（公式価格）",
    "Costs are counted at the official price times this, as a relay bills, like 0.8 or 1.5; a price you set for a model stays as set": "費用は公式価格にこの倍率を掛けて計算します（中継サービスの課金方式、例: 0.8 や 1.5）。モデルごとに設定した価格はそのままです",
