    "Its own name, every reasoning level it has, whether it sees images, the API it is asked on, the model it is the same as, and its list price": "元の名前、すべての推論レベル、画像対応の有無、リクエストに使う API、同じモデルの指定、公式価格",
    "What {id} costs, in US dollars per million tokens, as the Usage page counts it; empty: its list price, shown greyed. A price set here isn't multiplied by the provider's price rate": "{id} の価格（米ドル / 100 万トークン）。使用量ページはこれで計算します。空欄なら公式価格（灰色で表示）。ここで設定した価格にはプロバイダーの価格倍率は掛かりません",
    "Price, $ / 1M tokens": "価格（$ / 100 万トークン）",
