    "Send the smallest request to each API (OpenAI chat completions, Responses, Anthropic messages) at this URL, to see which answer": "この URL の各 API（OpenAI Chat Completions、Responses、Anthropic Messages）に最小のリクエストを送り、どれが応答するか調べます",
