    "Messages API. Claude Code reads ANTHROPIC_AUTH_TOKEN instead of the key; the Agents tab sets that for you.": "Messages API。Claude Code はキーの代わりに ANTHROPIC_AUTH_TOKEN を読みます。「エージェント」タブが設定します。",
