    "{n} Codex sessions were made with another provider ({from}): Codex lists only {to}'s sessions in its history now, so they don't show there.": "{n} 件の Codex セッションは別のプロバイダー（{from}）で作成されました。Codex の履歴には現在 {to} のセッションしか表示されないため、表示されません。",
