    "Updates are downloaded from GitHub; a mirror can be used where GitHub is slow": "更新は GitHub からダウンロードします。GitHub が遅い場合はミラーを使えます",
    "The update and its checksum always come from usemagpie.ai; a file from the mirror that doesn't match it is not installed.": "更新情報とチェックサムは常に usemagpie.ai から取得します。一致しないミラーのファイルはインストールされません。",
