    "Brings the {n} skills into the library: the agents that have them go on having them, and you can give them to the others": "{n} 個のスキルをライブラリに取り込みます：持っているエージェントはそのまま使え、他のエージェントにも渡せます",
    "{n} skills are in the library now": "{n} 個のスキルをライブラリに追加しました",
    "{name} wasn't brought in: {error}": "{name} を取り込めませんでした：{error}",
    "Turn all on": "すべてオン",
    "Turn all off": "すべてオフ",
    "Give every skill to all {n} agents that can take skills": "スキルを使える {n} 個のエージェントすべてに、全スキルを渡す",
    "Take every skill from all {n} agents": "{n} 個のエージェントすべてから全スキルを外す",
    "Turn off all {n} skills?": "{n} 個のスキルをすべてオフにしますか？",
    "Every skill is taken out of {agents}. They stay in the library, to turn on again.": "すべてのスキルが {agents} から外されます。ライブラリには残るので、再びオンにできます。",
