    "{n} skills are off for all {m} agents": "{n} 個のスキルを {m} 個のエージェントすべてでオフにしました",
    "By agent": "エージェント別",
    "Turn every skill on or off for one agent": "1つのエージェントで全スキルをオン／オフ",
    "Turn every server on or off for one agent": "1つのエージェントで全サーバーをオン／オフ",
    "Skills by agent": "エージェント別のスキル",
    "MCP servers by agent": "エージェント別の MCP サーバー",
    "Every skill on or off for one agent; the others keep theirs. Turned off, they stay in the library.": "1つのエージェントで全スキルをオン／オフします。他のエージェントはそのままです。オフにしたスキルはライブラリに残ります。",
    "Every server on or off for one agent; the others keep theirs. Turned off, they stay in the library.": "1つのエージェントで全サーバーをオン／オフします。他のエージェントはそのままです。オフにしたサーバーはライブラリに残ります。",
    "Hidden on the Agents page: it isn't given anything new, and what it has can be taken out here": "エージェントページで非表示：新しいものは渡されません。既にあるものはここで外せます",
    "Hidden on the Agents page: switch it off here to take the shared instructions out of its file": "エージェントページで非表示：ここでオフにすると、ファイルから共有指示を取り除きます",
