    "Give {agent} every server it can reach": "{agent} に接続できる全サーバーを渡す",
    "Take every skill from {agent}": "{agent} から全スキルを外す",
    "Take every server from {agent}": "{agent} から全サーバーを外す",
    "{n} skills are on for {agent}": "{agent} で {n} 個のスキルがオンです",
    "Every skill is off for {agent}": "{agent} ではすべてのスキルがオフです",
    "1 skill is on for {agent}": "{agent} で 1 個のスキルがオンです",
    "1 server is on for {agent}": "{agent} で 1 個のサーバーがオンです",
    "{n} servers are on for {agent}": "{agent} で {n} 個のサーバーがオンです",
    "Every server is off for {agent}": "{agent} ではすべてのサーバーがオフです",
    "Remove all": "すべて削除",
    "Take all {n} skills out of the library": "{n} 個のスキルをすべてライブラリから削除",
    "Remove all {n} skills?": "{n} 個のスキルをすべて削除しますか？",
    "They are taken out of the library and out of {agents}.": "ライブラリから削除され、{agents} からも外されます。",
    "They are taken out of the library; no agent has any of them.": "ライブラリから削除されます。これらを持っているエージェントはありません。",
    "The skills magpie placed in {n} projects are taken away too.": "magpie が {n} 個のプロジェクトに置いたスキルも取り除かれます。",
    "{n} folders are moved to magpie's backups (Backups, at the foot of the Library), not deleted.": "{n} 個のフォルダは削除されず、magpie のバックアップ（ライブラリ下部の「バックアップ」）に移されます。",
    "{n} linked from folders of your own are only unlinked: those folders stay where they are.": "自分のフォルダからリンクされた {n} 個はリンクが解除されるだけで、そのフォルダはそのまま残ります。",
    "Remove all {n}": "{n} 個すべて削除",
    "{n} skills removed": "{n} 個のスキルを削除しました",
    "{name} wasn't removed: {error}": "{name} を削除できませんでした：{error}",
    "Keeps it in the library: {agents} go on having it, and you can give it to the others": "ライブラリに保管します：{agents} はそのまま使え、他のエージェントにも渡せます",
    "＋ Add": "＋ 追加",
    "New MCP server": "新しい MCP サーバー",
    "or paste its JSON anywhere here": "または、ここに JSON を貼り付け",
    "e.g. github": "例：github",
    "Letters, digits, - and _ — what the agents call it": "英字、数字、- と _ — エージェントがこの名前で呼びます",
    "Command": "コマンド",
    "Runs as": "実行方法",
    "The command and its arguments, as you'd type them": "コマンドとその引数（入力するとおりに）",
    "Environment": "環境変数",
    "Remove from the library": "ライブラリから削除",
    "{name} is out of the library and the agents it was given to": "{name} をライブラリと渡していたエージェントから削除しました",
    "Filled in from what you pasted": "貼り付けた内容から入力しました",
    "{n} servers in what you pasted": "貼り付けた内容に {n} 個のサーバーがあります",
    "(no name)": "（名前なし）",
    "in the library": "ライブラリにあり",
    "Add 1 server": "1 個のサーバーを追加",
    "Add {n} servers": "{n} 個のサーバーを追加",
    "Added {n} servers": "{n} 個のサーバーを追加しました",
    "A skill is a folder with a SKILL.md an agent loads when it's needed. The library keeps each one once and links it into the agents you pick.": "スキルとは、エージェントが必要なときに読み込む SKILL.md を含むフォルダです。ライブラリは各スキルを1つだけ保管し、選んだエージェントにリンクします。",
    "In the library": "ライブラリ内",
    "By source": "ソース別",
    "Names from A to Z": "名前順（A→Z）",
    "Names from Z to A": "名前順（Z→A）",
    "not in the library — bring one in to give it to the others": "ライブラリにありません — 取り込むと他のエージェントにも渡せます",
    "{agents} has no skills folder.": "{agents} にはスキルフォルダがありません。",
    "Claude Desktop shows skill changes once its window is reloaded ({keys}). It gets a copy of each skill, and one you change in Desktop is left as it is.": "Claude Desktop はウィンドウを再読み込み（{keys}）するとスキルの変更を表示します。各スキルのコピーを受け取り、Desktop で変更したものはそのまま残ります。",
    "In projects": "プロジェクト内",
    "Add a project": "プロジェクトを追加",
    "Give a project's agents some of these skills as the project's own: magpie links them into its .claude/skills and .agents/skills and keeps them out of git.": "プロジェクトのエージェントに、これらのスキルの一部をプロジェクト固有のものとして渡します：magpie はそれらを .claude/skills と .agents/skills にリンクし、git の対象外にします。",
    "The project's folder, like ~/code/app": "プロジェクトのフォルダ（例：~/code/app）",
    "{name} added — pick the skills it gets": "{name} を追加しました — 渡すスキルを選んでください",
    "Folder is gone": "フォルダがありません",
    "Copies": "コピー",
    "No skills yet": "スキルはまだありません",
    "Remove the project": "プロジェクトを削除",
    "Hide its skills": "スキルを隠す",
    "Pick the skills it gets": "渡すスキルを選択",
    "Copy files instead of linking": "リンクではなくファイルをコピー",
    "{name} gets copies now": "{name} はコピーを使うようになりました",
    "{name} gets links now": "{name} はリンクを使うようになりました",
    "Copies are made again whenever the library's skill changes; edits made to them are replaced.": "ライブラリのスキルが変わるたびにコピーし直します。コピーへの編集は上書きされます。",
    "Links follow the library's skill: an update reaches the project at once.": "リンクはライブラリのスキルに追従します：アップデートはすぐにプロジェクトに反映されます。",
    "Not placed": "未配置",
    "{skill} is in {name} for {agents}": "{skill} を {name} に配置しました（{agents} 用）",
    "{skill} is out of {name}": "{skill} を {name} から外しました",
    "Placed in {dirs} of the project and listed in its .gitignore. A folder there that isn't magpie's is left as it is.": "プロジェクトの {dirs} に配置し、.gitignore に記載します。そこにある magpie のものでないフォルダはそのままです。",
    "{agents} reads no project skills folder magpie knows of.": "{agents} は magpie が把握しているプロジェクトのスキルフォルダを読みません。",
    "The skills and MCP servers magpie put in it are taken away, with their lines in its .gitignore. Nothing else in the folder is touched.": "magpie がそこに置いたスキルと MCP サーバーは、.gitignore の該当行とともに取り除かれます。フォルダ内の他のものには触れません。",
    "magpie forgets the project. The skills and MCP servers it put in the folder stay there as they are, with their lines in its .gitignore, and are yours from then on; a linked skill still follows the library's.": "magpie はこのプロジェクトを管理しなくなります。フォルダに置いたスキルと MCP サーバーは .gitignore の該当行とともにそのまま残り、以後はあなたのものになります。リンクされたスキルは引き続きライブラリのものに追従します。",
    "Keep its skills and MCP servers": "スキルと MCP サーバーを残す",
