    "More in Plugins": "プラグインにもっとあります",
    "Subscriptions magpie doesn't sign in to itself: install a plugin for one in the Plugins tab": "magpie が自分ではサインインしないサブスクリプション：「プラグイン」タブで対応するプラグインをインストールしてください",
    "look for a plugin": "プラグインを探す",
