    "magpie's icon before the allowances; off, the allowances alone, and a click on one still opens the panel": "利用枠の前に magpie のアイコンを表示します。オフにすると利用枠だけになり、クリックすると引き続きパネルが開きます",
    "At its cap · {agent} still uses it": "上限に到達 · {agent} は引き続き使用中",
    "A usage window is at {n}%, past this account's {cap}% cap: requests through magpie are refused with a usage-cap error until it renews": "利用枠が {n}% に達し、このアカウントの上限 {cap}% を超えています。更新されるまで、magpie 経由のリクエストは使用量上限エラーで拒否されます",
    "{agent} is signed in to this account and asks its vendor itself, not through magpie, so with no other account on to move it to, {agent} goes on using it past the cap. Add another account, or pick {agent}'s models via magpie, for the cap to hold it": "{agent} はこのアカウントでサインインしており、magpie を経由せず自分でベンダーに要求します。切り替え先となる有効なアカウントが他にないため、{agent} は上限を超えても使い続けます。上限を効かせるには、別のアカウントを追加するか、{agent} のモデルを magpie 経由で選んでください",
    "Discard unsaved changes? Your changes will be lost.": "未保存の変更を破棄しますか？変更は失われます。",
    "This removes the selected item. Continue?": "選択した項目を削除します。続行しますか？",
