    "This account or key will stop being used for requests. You will need to add it again to use it.": "このアカウントまたはキーはリクエストに使用されなくなります。再び使うには追加し直してください。",
    "This routing group will no longer be available to agents.": "このルーティンググループはエージェントから利用できなくなります。",
