    "Take out everything magpie wrote into {agent}'s config and put back what it had before": "Alles entfernen, was magpie in die Konfiguration von {agent} geschrieben hat, und den vorherigen Stand wiederherstellen",
    "put back what {agent} had before magpie": "Stand von {agent} vor magpie wiederherstellen",
    "Disconnect {agent} from magpie?": "{agent} von magpie trennen?",
    "magpie takes out everything it wrote into {agent}'s config — its endpoint, key, models and effort — and puts back the settings {agent} had before. magpie's providers and accounts stay as they are.": "magpie entfernt alles, was es in die Konfiguration von {agent} geschrieben hat — Endpunkt, Schlüssel, Modelle und Reasoning-Effort — und stellt die vorherigen Einstellungen von {agent} wieder her. Anbieter und Konten in magpie bleiben unverändert.",
    "Disconnect": "Trennen",
