    "Reading what changes…": "Änderungen werden gelesen…",
    "magpie's provider table stays, so sessions opened on magpie's models still open": "Die Anbietertabelle von magpie bleibt, damit Sitzungen mit magpie-Modellen weiter geöffnet werden können",
    "Running {agent} copies take it once reopened": "Laufende {agent}-Instanzen übernehmen es nach dem Neuöffnen",
    "Switch an agent on and the models you set up in magpie show up as the {magpie} provider in its own model list; or pick its model right here.": "Schalten Sie einen Agenten ein, erscheinen Ihre in magpie eingerichteten Modelle als Anbieter {magpie} in seiner Modellliste; oder wählen Sie sein Modell direkt hier.",
    "Pick a model": "Modell wählen",
    "Pick one of magpie's models: {agent} is connected and starts on it": "Eines der magpie-Modelle wählen: {agent} wird verbunden und startet damit",
    "Its last pick": "Seine letzte Auswahl",
    "Unset, {agent} starts on its own last pick": "Nicht festgelegt: {agent} startet mit seiner letzten Auswahl",
    "Connected · starts on the model picked here": "Verbunden · startet mit dem hier gewählten Modell",
    "Let your agents use the models you set up in magpie": "Ihre Agenten die in magpie eingerichteten Modelle nutzen lassen",
    "Switch an agent on and your models show up as the magpie provider in its own model list, to change in the agent. Or pick a model right here: the agent is connected and starts on it. Switch it off and it goes back to how it was.": "Schalten Sie einen Agenten ein, erscheinen Ihre Modelle als Anbieter magpie in seiner Modellliste und lassen sich im Agenten wechseln. Oder wählen Sie hier ein Modell: Der Agent wird verbunden und startet damit. Ausgeschaltet kehrt er zum vorherigen Stand zurück.",
    "Connected · pick magpie's models with {cmd} in {agent}": "Verbunden · magpie-Modelle mit {cmd} in {agent} wählen",
    "Connected · magpie's models are in {agent}'s model list": "Verbunden · magpie-Modelle stehen in der Modellliste von {agent}",
    "Connect {agent} to magpie": "{agent} mit magpie verbinden",
    "Add a provider or subscription in magpie first, then connect {agent}": "Fügen Sie zuerst in magpie einen Anbieter oder ein Abo hinzu und verbinden Sie dann {agent}",
    "Connected · switch off to put back what {agent} had before magpie": "Verbunden · ausschalten, um den Stand von {agent} vor magpie wiederherzustellen",
    "Switch on and {agent}'s model list gets magpie's models": "Einschalten, dann erhält die Modellliste von {agent} die magpie-Modelle",
    "{agent} is connected to magpie": "{agent} ist mit magpie verbunden",
    "{agent} is connected to magpie · back on {model}, what it was on when it was switched off": "{agent} ist mit magpie verbunden · wieder auf {model}, wie beim Ausschalten",
    "{agent} is connected to magpie · on {model} through magpie, the model it was on": "{agent} ist mit magpie verbunden · nutzt über magpie {model}, sein bisheriges Modell",
    "{agent} is connected to magpie · on {model} through magpie: it had no model set, so the first of its own": "{agent} ist mit magpie verbunden · nutzt über magpie {model}: kein Modell war festgelegt, daher das erste eigene",
    "{agent} is connected to magpie · on {model} through magpie: magpie doesn't serve the model it was on": "{agent} ist mit magpie verbunden · nutzt über magpie {model}: magpie stellt das bisherige Modell nicht bereit",
    "{agent} is connected to magpie · it stays on its own last pick; magpie's models join its {cmd}": "{agent} ist mit magpie verbunden · bleibt bei seiner letzten Auswahl; magpie-Modelle kommen zu {cmd} hinzu",
    "via magpie": "über magpie",
    "{agent} asks magpie for it": "{agent} fragt es bei magpie an",
    "direct, not via magpie": "direkt, nicht über magpie",
    "off magpie": "ohne magpie",
    "{agent} as installed: magpie's endpoint and models come out": "{agent} wie installiert: Endpunkt und Modelle von magpie werden entfernt",
    "Take {agent} off magpie?": "{agent} von magpie lösen?",
    "Default is {agent} as installed: magpie's endpoint and models come out, and {agent} starts on its own default model. What it had before magpie isn't put back; Disconnect and restore does that.": "„Standard“ ist {agent} wie installiert: Endpunkt und Modelle von magpie werden entfernt, und {agent} startet mit seinem eigenen Standardmodell. Der Stand vor magpie wird nicht wiederhergestellt; das erledigt „Trennen und wiederherstellen“.",
    "{model} is {agent}'s own model: {agent} asks {vendor} for it itself, with its own sign-in, not through magpie. Picking it takes {agent} off magpie, and it starts on {model}.": "{model} ist ein eigenes Modell von {agent}: {agent} fragt es mit eigener Anmeldung direkt bei {vendor} an, nicht über magpie. Bei dieser Auswahl wird {agent} von magpie gelöst und startet mit {model}.",
    "「接入」 goes off, and {agent} is listed under Not set up with the agents not connected. Switch it on again to go back through magpie.": "„Verbinden“ wird ausgeschaltet, und {agent} erscheint mit den nicht verbundenen Agenten unter „Nicht eingerichtet“. Wieder einschalten, um erneut über magpie zu laufen.",
    "「接入」 goes off. Switch it on again to go back through magpie.": "„Verbinden“ wird ausgeschaltet. Wieder einschalten, um erneut über magpie zu laufen.",
    "Use default": "Standard verwenden",
    "Use {model}": "{model} verwenden",
    "{agent} no longer goes through magpie · on its own default": "{agent} läuft nicht mehr über magpie · nutzt seinen eigenen Standard",
    "{agent} no longer goes through magpie; its own settings are back": "{agent} läuft nicht mehr über magpie; seine eigenen Einstellungen sind wiederhergestellt",
    "Update to {v}": "Auf {v} aktualisieren",
