    "Keep magpie in the Dock too, always or while its window is open, for Cmd-Tab and a menu bar too full to show its icon": "magpie auch im Dock halten, immer oder solange das Fenster offen ist, für Cmd-Tab und eine Menüleiste, die zu voll für das Symbol ist",
