    "Keeps this computer from going to sleep by itself while agents work through magpie and for ten minutes after; the display may still turn off": "Verhindert, dass dieser Computer von selbst in den Ruhezustand geht, während Agenten über magpie arbeiten, und zehn Minuten danach; der Bildschirm kann sich trotzdem ausschalten",
