    "Image generation": "Bilderzeugung",
    "The model Magpie Image draws with. Give an agent the tool from Library → MCP servers → Discover → Magpie Image; images are saved in its project": "Das Modell, mit dem Magpie Image zeichnet. Geben Sie einem Agenten das Tool über Bibliothek → MCP-Server → Entdecken → Magpie Image; Bilder werden in seinem Projekt gespeichert",
    "Agents given Magpie Image can't generate images or videos: the tool says it is off": "Agenten mit Magpie Image können keine Bilder oder Videos erzeugen: das Tool meldet, dass es ausgeschaltet ist",
    "no model that draws": "kein Modell zur Bilderzeugung",
    "no images generated": "keine Bilderzeugung",
    "Generate and edit images with the image model set in Magpie (Settings → Images), and make short videos with a Grok subscription, saved in the project.": "Bilder mit dem in Magpie festgelegten Bildmodell (Einstellungen → Bilder) erzeugen und bearbeiten sowie kurze Videos mit einem Grok-Abo erstellen, gespeichert im Projekt.",
    "Pick the agents that may generate images: each image costs what the model set in Settings → Images charges.": "Agenten wählen, die Bilder erzeugen dürfen: jedes Bild kostet, was das unter Einstellungen → Bilder festgelegte Modell berechnet.",
