    "Codex subagents on any model": "Codex-Subagenten auf jedem Modell",
    "Long conversations": "Lange Unterhaltungen",
    "Codex and Claude Code compact a conversation at 272K tokens, or the size typed here, on a model with a larger window, unless its provider has a Compact at of its own; in Claude Code a Claude model runs to its own window, 1M for a [1m] one, as Anthropic runs it. The model’s full window lets any conversation grow further, with every turn slower and costlier": "Codex und Claude Code komprimieren eine Unterhaltung bei einem Modell mit größerem Kontextfenster ab 272K Token oder der hier eingegebenen Größe, sofern der Anbieter keinen eigenen Wert unter „Komprimieren ab“ hat; in Claude Code nutzt ein Claude-Modell sein eigenes Fenster, 1M bei einem [1m]-Modell, wie Anthropic es betreibt. Mit dem vollen Fenster des Modells wächst jede Unterhaltung weiter, wobei jede Runde langsamer und teurer wird",
    "Full window": "Volles Fenster",
    "Compact at {n}": "Bei {n} komprimieren",
