    "Codex’s auto-review decides approvals on this model, whatever model the conversation is on": "Codex’ Auto-Review entscheidet Freigaben mit diesem Modell, egal auf welchem Modell die Unterhaltung läuft",
    "Codex’s auto-review decides approvals on codex-auto-review when it has it, else on the conversation’s model at low effort": "Codex’ Auto-Review entscheidet Freigaben mit codex-auto-review, wenn vorhanden, sonst mit dem Modell der Unterhaltung bei niedrigem Aufwand",
    "no title, nothing sent": "kein Titel, nichts gesendet",
    "Codex asks its own model for each thread’s title through its ChatGPT sign-in, even while the conversation is on magpie’s models": "Codex fragt über seine ChatGPT-Anmeldung sein eigenes Modell nach dem Titel jedes Threads, auch wenn die Unterhaltung auf magpie-Modellen läuft",
    "Codex’s title requests are answered by magpie with no title and sent nowhere; new threads stay unnamed": "Titelanfragen von Codex beantwortet magpie ohne Titel und leitet sie nirgends weiter; neue Threads bleiben unbenannt",
    "Codex’s title requests go to this model, not to its ChatGPT sign-in; the Usage and Routing views still show them as titles": "Titelanfragen von Codex gehen an dieses Modell statt über die ChatGPT-Anmeldung; die Ansichten „Nutzung“ und „Weiterleitung“ zeigen sie weiterhin als Titel",
    "Codex’s OpenAI models hand subagents their tasks as text (multi-agent V1), so a GPT lead can spawn them on magpie’s other models. New threads only; Codex’s own multi_agent_v2 setting still wins": "Die OpenAI-Modelle von Codex übergeben Subagenten ihre Aufgaben als Text (multi-agent V1), sodass ein leitendes GPT sie auf anderen magpie-Modellen starten kann. Nur neue Threads; die Codex-Einstellung multi_agent_v2 hat weiterhin Vorrang",
