    "its web search": "seine Websuche",
    "A Kimi Code plan ({names}) searches for its own models first, with its web search; for other models only when named here": "Ein Kimi-Code-Tarif ({names}) sucht zuerst mit seiner Websuche für die eigenen Modelle; für andere Modelle nur, wenn er hier gewählt ist",
    "{names} search for their own models first, with Gemini's Google Search": "{names} suchen für ihre eigenen Modelle zuerst mit der Google-Suche von Gemini",
