    "{agent} is signed in to {user} now: sign it in to another of its accounts first (Use on that account), then remove this one": "{agent} ist gerade bei {user} angemeldet: Melden Sie es zuerst bei einem anderen seiner Konten an (dort „Verwenden“) und entfernen Sie dann dieses",
    "Signs Codex out of this account, as codex logout does": "Meldet Codex von diesem Konto ab, wie codex logout",
    "Codex is signed in to another of its accounts, and magpie forgets this one; the account itself is untouched": "Codex wird bei einem anderen seiner Konten angemeldet, und magpie vergisst dieses; das Konto selbst bleibt unberührt",
