    "Move {name}": "{name} verschieben",
    "Enter adds {id}": "Enter fügt {id} hinzu",
    "No model matches": "Kein Modell passt",
    "When {name} is out of quota, rate limited or down, a request goes to these instead, top first. It only happens before any of the reply is sent, and {name} then sits out a minute.": "Hat {name} kein Kontingent mehr, wird gedrosselt oder fällt aus, geht eine Anfrage stattdessen an diese, von oben nach unten. Das geschieht nur, bevor ein Teil der Antwort gesendet wurde, und {name} pausiert dann eine Minute.",
    "{agent} and the gateway use the one in use. Sessions already running keep theirs until restarted.": "{agent} und der Zugangspunkt verwenden das Konto „In Verwendung“. Laufende Sitzungen behalten ihres bis zum Neustart.",
    "The gateway uses the first. Tick more and it moves on to the next when the one before it is out of quota. {agent} itself stays signed in as it is.": "Der Zugangspunkt verwendet das erste. Haken Sie weitere an, wechselt er zum nächsten, sobald das vorherige kein Kontingent mehr hat. {agent} selbst bleibt angemeldet wie bisher.",
    "The gateway uses the first. Tick more and it moves on to the next when the one before it is out of quota.": "Der Zugangspunkt verwendet das erste. Haken Sie weitere an, wechselt er zum nächsten, sobald das vorherige kein Kontingent mehr hat.",
    "Runs on": "Läuft über",
    "Use the built-in again": "Wieder integrierte Version verwenden",
    "Move to the plugin": "Zur Erweiterung umziehen",
    "magpie's built-in · or the community {name} plugin, with the same accounts": "in magpie integriert · oder die Community-Erweiterung {name}, mit denselben Konten",
    "The community {name} plugin, with the accounts you had here.": "Die Community-Erweiterung {name}, mit den Konten, die Sie hier hatten.",
    "It stays built-in: {error}": "Es bleibt integriert: {error}",
    "Installing the plugin and checking each account…": "Erweiterung wird installiert und jedes Konto geprüft…",
    "magpie couldn't reach npm to install the plugin. Check the network or proxy, then try again.": "magpie konnte npm zum Installieren der Erweiterung nicht erreichen. Prüfen Sie Netzwerk oder Proxy und versuchen Sie es erneut.",
    "npm couldn't install the plugin: {line}": "npm konnte die Erweiterung nicht installieren: {line}",
    "every {name} account needs signing in again. Sign one in above, then move.": "jedes {name}-Konto muss neu angemeldet werden. Melden Sie oben eines an und ziehen Sie dann um.",
    "every {name} account needs signing in again. Sign one in under Providers, then move.": "jedes {name}-Konto muss neu angemeldet werden. Melden Sie unter Anbieter eines an und ziehen Sie dann um.",
    "the plugin doesn't serve {models}. Untick them under Models, or keep the built-in.": "die Erweiterung stellt {models} nicht bereit. Entfernen Sie unter Modelle die Haken oder behalten Sie die integrierte Version.",
    "the plugin doesn't serve {models} for {user}, though the built-in does. Untick them under Models, or keep the built-in.": "die Erweiterung stellt {models} für {user} nicht bereit, die integrierte Version schon. Entfernen Sie unter Modelle die Haken oder behalten Sie die integrierte Version.",
    "{user} doesn't work through the plugin: {error}": "{user} funktioniert nicht über die Erweiterung: {error}",
    "{name} now runs on its plugin — {accounts}, {models}. Use the built-in again from here any time.": "{name} läuft jetzt über seine Erweiterung — {accounts}, {models}. Von hier aus können Sie jederzeit zur integrierten Version zurückkehren.",
    "{name} now runs on its plugin — {accounts}, {models}. Its editor in Providers moves it back.": "{name} läuft jetzt über seine Erweiterung — {accounts}, {models}. Über seinen Editor unter Anbieter wechseln Sie zurück.",
    "{name} is built-in again, with its accounts": "{name} ist wieder integriert, mit seinen Konten",
    "{n} account": "{n} Konto",
    "Deprecated": "Veraltet",
    "Some subscriptions are reached in ways their vendors' terms may not allow. So that magpie itself isn't banned over them, subscription providers are being decoupled from magpie and run by community plugins instead.": "Manche Abos werden auf eine Weise genutzt, die die Bedingungen ihrer Anbieter möglicherweise nicht erlauben. Damit magpie selbst deswegen nicht gesperrt wird, werden Abo-Anbieter von magpie entkoppelt und stattdessen von Community-Erweiterungen betrieben.",
    "These built-in subscriptions are deprecated: {names}": "Diese integrierten Abos sind veraltet: {names}",
    "{name}'s built-in subscription is deprecated": "Das integrierte Abo von {name} ist veraltet",
    "Moving keeps your accounts, models and agents as they are.": "Beim Umzug bleiben Ihre Konten, Modelle und Agenten unverändert.",
    "Review the move": "Umzug prüfen",
    "Review in Plugins": "Unter Erweiterungen prüfen",
    "Hide this until another deprecated subscription is signed in": "Ausblenden, bis ein weiteres veraltetes Abo angemeldet wird",
