    "{name} runs on magpie's built-in, with your accounts; Move {name} here runs it on this plugin": "{name} läuft über die integrierte Version von magpie mit Ihren Konten; „{name} hierher umziehen“ lässt es über diese Erweiterung laufen",
    "Move my {n} {name} account": "{n} {name}-Konto umziehen",
    "Move my {n} {name} accounts": "{n} {name}-Konten umziehen",
