    "The team plan's resets, used on bigmodel.cn or z.ai": "Die Resets des Team-Tarifs, einlösbar auf bigmodel.cn oder z.ai",
    "until {when}": "bis {when}",
    "The first runs out {when}": "Der erste läuft {when} ab",
    "Reset {n} runs out {when}": "Reset {n} läuft {when} ab",
    "Reset {n} never runs out": "Reset {n} läuft nie ab",
    "Five-hour reset runs out {when}": "Fünf-Stunden-Reset läuft {when} ab",
