    "Weekly reset runs out {when}": "Wochen-Reset läuft {when} ab",
    "Weekly reset never runs out": "Wochen-Reset läuft nie ab",
    "Use one…": "Einen einlösen…",
    "Use a reset": "Reset einlösen",
    "Its week was used up, so one of {account}'s Codex resets was used by itself first.": "Die Woche war aufgebraucht, daher wurde zuerst automatisch einer der Codex-Resets von {account} eingelöst.",
    "{who} answered {status}: its week is used up and nobody else could take the request, so one of {account}'s Codex resets was used by itself and the request is asked again, before any of the reply reaches {agent}.": "{who} antwortete {status}: Die Woche ist aufgebraucht und kein anderes Konto konnte die Anfrage übernehmen, daher wurde automatisch einer der Codex-Resets von {account} eingelöst und die Anfrage erneut gestellt, bevor ein Teil der Antwort {agent} erreicht.",
    "{who} no longer uses a reset by itself": "{who} löst keinen Reset mehr automatisch ein",
    "Auto-use resets": "Resets automatisch einlösen",
    "Auto-use resets:": "Resets automatisch einlösen:",
    "when the week runs out, or before one expires": "wenn die Woche aufgebraucht ist oder bevor einer abläuft",
    "Auto-use": "Automatisch",
    "Auto-use: on": "Automatisch: an",
    "Auto-use: off": "Automatisch: aus",
    "auto-used before it expires": "wird vor Ablauf automatisch eingelöst",
    "not auto-used": "wird nicht automatisch eingelöst",
    "Auto-use is on: the reset that runs out first is used about half an hour before it does, if this account's windows have been used, so what they have left can be used until then and it isn't lost; at once if the account is held up until after then.": "Automatisches Einlösen ist an: Der zuerst ablaufende Reset wird etwa eine halbe Stunde vor Ablauf eingelöst, sofern die Zeitfenster dieses Kontos genutzt wurden; so lässt sich der Rest bis dahin nutzen, und der Reset verfällt nicht. Ist das Konto bis nach dem Ablauf blockiert, wird er sofort eingelöst.",
    "Auto-use is off: the reset that runs out first is lost unless it's used by hand before then.": "Automatisches Einlösen ist aus: Der zuerst ablaufende Reset verfällt, sofern er nicht vorher von Hand eingelöst wird.",
    "On: a reset is used by itself when this account's week is used up and no other account can answer, one a week at most, and the one about to run out is used about half an hour before it does, if the account has been used, or at once when the account is held up until after then. Otherwise the five hours running out never uses one. Click to turn it off.": "An: Ein Reset wird automatisch eingelöst, wenn die Woche dieses Kontos aufgebraucht ist und kein anderes Konto antworten kann, höchstens einer pro Woche; der bald ablaufende wird etwa eine halbe Stunde vor Ablauf eingelöst, sofern das Konto genutzt wurde, oder sofort, wenn das Konto bis danach blockiert ist. Ein aufgebrauchtes Fünf-Stunden-Fenster allein löst nie einen ein. Zum Ausschalten klicken.",
    "Off: this account's resets are used only by hand. Turned on, one is used by itself when its week is used up and no other account can answer, one a week at most, and the one about to run out about half an hour before it does, if the account has been used, or at once when the account is held up until after then. Otherwise the five hours running out never uses one.": "Aus: Die Resets dieses Kontos werden nur von Hand eingelöst. Eingeschaltet wird einer automatisch eingelöst, wenn die Woche aufgebraucht ist und kein anderes Konto antworten kann, höchstens einer pro Woche, und der bald ablaufende etwa eine halbe Stunde vor Ablauf, sofern das Konto genutzt wurde, oder sofort, wenn das Konto bis danach blockiert ist. Ein aufgebrauchtes Fünf-Stunden-Fenster allein löst nie einen ein.",
    "{who} uses a reset by itself when its week runs out, or before one expires": "{who} löst automatisch einen Reset ein, wenn die Woche aufgebraucht ist oder bevor einer abläuft",
    "Uses the reset that runs out first ({when}), never one that lasts longer.": "Löst den zuerst ablaufenden Reset ein ({when}), nie einen länger gültigen.",
    "Uses one of its resets; none of them runs out.": "Löst einen der Resets ein; keiner davon läuft ab.",
    "This account's windows start again at once, as if none had been used. You're asked before anything is spent.": "Die Zeitfenster dieses Kontos beginnen sofort neu, als wäre nichts verbraucht. Vor dem Einlösen werden Sie gefragt.",
    "The one used is the one that runs out first, {when}.": "Eingelöst wird der zuerst ablaufende, {when}.",
    "Use a Codex reset?": "Codex-Reset einlösen?",
    "nothing to reset — no window is used up yet, and the reset is kept": "nichts zurückzusetzen — noch kein Zeitfenster ist aufgebraucht, der Reset bleibt erhalten",
    "a reset was used a short while ago — try again later": "vor Kurzem wurde ein Reset eingelöst — versuchen Sie es später erneut",
    "the account can't use a reset": "das Konto kann keinen Reset einlösen",
    "resets can't be used right now — try again later": "Resets können gerade nicht eingelöst werden — versuchen Sie es später erneut",
    "{who} has 1 reset. Using it starts its windows again at once, as if none of them had been used. It can't be undone.": "{who} hat 1 Reset. Beim Einlösen beginnen die Zeitfenster sofort neu, als wäre nichts verbraucht. Das lässt sich nicht rückgängig machen.",
    "{who} has {n} resets. Using one starts its windows again at once, as if none of them had been used. It can't be undone.": "{who} hat {n} Resets. Beim Einlösen eines Resets beginnen die Zeitfenster sofort neu, als wäre nichts verbraucht. Das lässt sich nicht rückgängig machen.",
    "None of its windows has been used yet, so there is nothing to start again.": "Keines der Zeitfenster wurde bisher genutzt, es gibt also nichts neu zu starten.",
    "1 window started again": "1 Zeitfenster neu gestartet",
    "{n} windows started again": "{n} Zeitfenster neu gestartet",
    "nothing to start again — no window has been used, and the reset is kept": "nichts neu zu starten — kein Zeitfenster wurde genutzt, der Reset bleibt erhalten",
    "no reset left on the account": "kein Reset mehr auf dem Konto",
    "that reset was already used": "dieser Reset wurde bereits eingelöst",
    "Allowances": "Kontingente",
    "What is left on the account: the vendor tells only this, so Used / Left leaves it as it is": "Was auf dem Konto übrig ist: Der Anbieter meldet nur diesen Wert, daher lässt „Verbraucht / Übrig“ ihn unverändert",
    "What is left on the account besides its windows": "Was neben den Zeitfenstern auf dem Konto übrig ist",
    "Headers": "Header",
    "Sign-in": "Anmeldung",
    "For a server that asks you to sign in (OAuth): magpie signs in once, and every agent given it uses that sign-in": "Für einen Server, der eine Anmeldung verlangt (OAuth): magpie meldet sich einmal an, und jeder Agent, dem er zugewiesen ist, nutzt diese Anmeldung",
    "Opening the sign-in…": "Anmeldung wird geöffnet…",
    "this server already works without signing in, so there is nothing to sign in to: the agents given it can use it as it is. A key it takes goes in Headers; a server that signs in at another address (as Exa's ?login) needs that URL": "dieser Server funktioniert bereits ohne Anmeldung, es gibt also nichts anzumelden: Die zugewiesenen Agenten können ihn direkt nutzen. Ein Schlüssel, den er erwartet, gehört unter Header; ein Server, der sich an einer anderen Adresse anmeldet (wie Exa mit ?login), braucht diese URL",
    "Finish signing in in your browser…": "Schließen Sie die Anmeldung im Browser ab…",
    "The agents given it use magpie's sign-in": "Die zugewiesenen Agenten nutzen die Anmeldung von magpie",
    "1 tool": "1 Tool",
    "{n} tools": "{n} Tools",
