    "The server asks for a sign-in": "Der Server verlangt eine Anmeldung",
    "The server refused magpie (HTTP {code}) — a key in its headers may be missing or wrong": "Der Server hat magpie abgelehnt (HTTP {code}) — ein Schlüssel in seinen Headern fehlt möglicherweise oder ist falsch",
    "can't start: {cmd} not found": "Start nicht möglich: {cmd} nicht gefunden",
    "Can't start it: there is no {cmd} on the PATH magpie has": "Start nicht möglich: {cmd} ist nicht im PATH von magpie",
