    "Sign-in required": "Anmeldung erforderlich",
    "sign-in required": "Anmeldung erforderlich",
    "Sign in again to use this account": "Melden Sie sich erneut an, um dieses Konto zu verwenden",
    "Claude Code is no longer signed in; sign in again in magpie": "Claude Code ist nicht mehr angemeldet; melden Sie sich in magpie erneut an",
    "its sign-in is gone; sign in again": "die Anmeldung ist nicht mehr vorhanden; melden Sie sich erneut an",
    "Claude Code could not authenticate this account; sign in again in magpie": "Claude Code konnte dieses Konto nicht authentifizieren; melden Sie sich in magpie erneut an",
    "Tested {user}: {result}": "{user} getestet: {result}",
    "{who} could not authenticate. Sign in again in magpie; this login is not retried. The request went to {next}.": "{who} konnte sich nicht authentifizieren. Melden Sie sich in magpie erneut an; diese Anmeldung wird nicht erneut versucht. Die Anfrage ging an {next}.",
    "{who} could not authenticate. Sign in again in magpie; this login is not retried. No other account could answer.": "{who} konnte sich nicht authentifizieren. Melden Sie sich in magpie erneut an; diese Anmeldung wird nicht erneut versucht. Kein anderes Konto konnte antworten.",
    "Open it to sign in again": "Öffnen, um sich erneut anzumelden",
    "Signed in to {name} — the agents given it use magpie's sign-in": "Bei {name} angemeldet — die zugewiesenen Agenten nutzen die Anmeldung von magpie",
    "Signed out of {name} — the agents are given the server's own address again": "Von {name} abgemeldet — die Agenten erhalten wieder die eigene Adresse des Servers",
    "Extra HTTP headers sent to the vendor, applied after auth. For gateways that need a private scheme.": "Zusätzliche HTTP-Header, die an den Anbieter gesendet und nach der Authentifizierung angewendet werden. Für Zugangspunkte mit eigenem Schema.",
