    "Requests to it go through this proxy: http://, https:// or socks5://": "Anfragen gehen über diesen Proxy: http://, https:// oder socks5://",
    "Proxy: type its address, like http://127.0.0.1:7890": "Proxy: Adresse eingeben, z. B. http://127.0.0.1:7890",
    "Provider's proxy": "Proxy des Anbieters",
