    "{name} is reached through its own API, which magpie translates each agent request for, so a test request can't be sent to it on its own. Ask the model from an agent to try it.": "{name} wird über eine eigene API erreicht, für die magpie jede Agentenanfrage übersetzt; eine eigenständige Testanfrage ist daher nicht möglich. Fragen Sie das Modell aus einem Agenten heraus an, um es auszuprobieren.",
