    "Its own name, every reasoning level it has, whether it sees images, the API it is asked on, the model it is the same as, and its list price": "Eigener Name, alle Reasoning-Stufen, Bildunterstützung, die angefragte API, das Modell, dem es entspricht, und der Listenpreis",
    "What {id} costs, in US dollars per million tokens, as the Usage page counts it; empty: its list price, shown greyed. A price set here isn't multiplied by the provider's price rate": "Was {id} kostet, in US-Dollar pro Million Tokens, wie die Nutzungsseite rechnet; leer: der Listenpreis (grau). Ein hier gesetzter Preis wird nicht mit dem Preisfaktor des Anbieters multipliziert",
    "Price, $ / 1M tokens": "Preis, $ / 1 Mio. Tokens",
