    "The model other providers serve that {id} is the same as: the routing groups magpie finds put them together. Empty: by its own id": "Das Modell anderer Anbieter, dem {id} entspricht: Die von magpie gefundenen Weiterleitungsgruppen fassen sie zusammen. Leer: nach eigener ID",
    "The API {id} is asked on. Auto: as the vendor's list says, else each URL the provider has; pick one when the vendor serves it on that one only": "Die API, über die {id} angefragt wird. Automatisch: laut Modellliste des Anbieters, sonst jede hinterlegte URL; wählen Sie eine, wenn der Anbieter es nur dort bereitstellt",
