    "Ask every model picked below on each API, to see which API serves which model (up to {n}, a few at a time)": "Jedes unten gewählte Modell über jede API anfragen, um zu sehen, welche API welches Modell bereitstellt (bis zu {n}, einige gleichzeitig)",
    "Pick models first, or type one and press Detect APIs": "Wählen Sie zuerst Modelle oder geben Sie eines ein und klicken Sie auf „APIs erkennen“",
