    "Set the URLs of the APIs that answered, and give each model that answered on one API only that API (staged in Names & levels, made with the Save)": "URLs der antwortenden APIs eintragen und jedem Modell, das nur über eine API geantwortet hat, nur diese API zuweisen (vorgemerkt unter „Namen & Stufen“, übernommen beim Speichern)",
