    "Send the smallest request to each API (OpenAI chat completions, Responses, Anthropic messages) at this URL, to see which answer": "Eine minimale Anfrage an jede API (OpenAI Chat Completions, Responses, Anthropic Messages) unter dieser URL senden, um zu sehen, welche antworten",
