    "Their files are moved to magpie's trash ({dir}), not erased: Trash puts them back. A session written to in the last minute is left alone, as {agent} may still be running it.": "Die Dateien werden in den Papierkorb von magpie ({dir}) verschoben, nicht gelöscht: Über „Papierkorb“ lassen sie sich wiederherstellen. Eine Sitzung, in die in der letzten Minute geschrieben wurde, bleibt unberührt, da {agent} sie eventuell noch ausführt.",
    "Moved to magpie's trash": "In den Papierkorb von magpie verschoben",
    "1 Codex session was made with another provider ({from}): Codex lists only {to}'s sessions in its history now, so it doesn't show there.": "1 Codex-Sitzung wurde mit einem anderen Anbieter ({from}) erstellt: Codex zeigt in seinem Verlauf jetzt nur Sitzungen von {to}, daher erscheint sie dort nicht.",
    "{n} Codex sessions were made with another provider ({from}): Codex lists only {to}'s sessions in its history now, so they don't show there.": "{n} Codex-Sitzungen wurden mit einem anderen Anbieter ({from}) erstellt: Codex zeigt in seinem Verlauf jetzt nur Sitzungen von {to}, daher erscheinen sie dort nicht.",
    "Move to {to}…": "Zu {to} umziehen…",
