    "Signed out — add this account again to use it": "Abgemeldet – fügen Sie dieses Konto erneut hinzu, um es zu nutzen",
    "Needs a Google Cloud project — hover for how": "Benötigt ein Google-Cloud-Projekt – für Anleitung darüberfahren",
    "Google no longer serves personal accounts to Gemini CLI — hover for more": "Google bedient private Konten nicht mehr über Gemini CLI – für mehr darüberfahren",
