    "This key has no limit — add the account's access token in the provider's settings to see its balance": "Dieser Schlüssel hat kein Limit – tragen Sie das Zugriffstoken des Kontos in den Anbietereinstellungen ein, um das Guthaben zu sehen",
    "AiHubMix didn't take the access token — paste a new one in the provider's settings": "AiHubMix hat das Zugriffstoken nicht akzeptiert – fügen Sie in den Anbietereinstellungen ein neues ein",
    "Account balance": "Kontoguthaben",
    "Step Plan allowances": "Step-Plan-Kontingente",
    "Team org ID": "Team-Organisations-ID",
    "Team project ID": "Team-Projekt-ID",
    "optional · only for a team plan": "optional · nur für einen Team-Plan",
    "Only for a key on a team's GLM Coding Plan: both are in {p}'s console, under the team's organization and project. With them the Usage page shows the team's 5-hour and weekly windows.": "Nur für einen Schlüssel eines Team-GLM-Coding-Plans: Beide finden Sie in der Konsole von {p} unter Organisation und Projekt des Teams. Damit zeigt die Seite „Nutzung“ die 5-Stunden- und Wochen-Zeitfenster des Teams.",
    "Team plan: give both the organization ID and the project ID": "Team-Plan: Geben Sie sowohl die Organisations-ID als auch die Projekt-ID an",
    "A key tells only the balance. The Step Plan's 5-hour, weekly and credit windows are told only to a StepFun sign-in: bring yours here once and magpie keeps it (for 30 days), used for nothing else.": "Ein Schlüssel liefert nur das Guthaben. Die 5-Stunden-, Wochen- und Credit-Zeitfenster des Step Plans gibt es nur mit einer StepFun-Anmeldung: Bringen Sie Ihre einmal hierher, magpie bewahrt sie (30 Tage) auf und nutzt sie für nichts anderes.",
    "Signed in · the Usage page shows the Step Plan": "Angemeldet · die Seite „Nutzung“ zeigt den Step Plan",
    "Sign out": "Abmelden",
    "Sign in to StepFun in your browser ↗": "Im Browser bei StepFun anmelden ↗",
    "Drag ": "Ziehen Sie ",
    " to the bookmarks bar (or ": " in die Lesezeichenleiste (oder ",
    "copy it": "kopieren Sie es",
    " as a bookmark's URL), then click it on the signed-in page": " als URL eines Lesezeichens) und klicken Sie es dann auf der angemeldeten Seite an",
    "paste what it copied": "Kopiertes einfügen",
    "Bookmarklet": "Bookmarklet",
    "Signed in to StepFun": "Bei StepFun angemeldet",
    "saved · paste a new one to replace it": "gespeichert · zum Ersetzen ein neues einfügen",
    "optional · the account's system access token": "optional · das System-Zugriffstoken des Kontos",
    "What the Balance URL is asked with in place of the key, when it wants the account's own token: a new-api relay's System Access Token, or a sub2api panel's login token (a JWT, sent as a Bearer); it is used for nothing else.": "Damit wird die Guthaben-URL statt mit dem Schlüssel abgefragt, wenn sie das eigene Token des Kontos verlangt: das System Access Token eines new-api-Relays oder das Login-Token eines sub2api-Panels (ein JWT, als Bearer gesendet); es wird für nichts anderes verwendet.",
    "…/api/usage/token takes the API key, not this token: a new-api relay tells the account's balance to the token at /api/user/self.": "…/api/usage/token erwartet den API-Schlüssel, nicht dieses Token: Ein new-api-Relay liefert das Kontoguthaben für das Token unter /api/user/self.",
    "The token needs a Balance URL: a new-api relay tells the account's balance to it at /api/user/self.": "Das Token braucht eine Guthaben-URL: Ein new-api-Relay liefert das Kontoguthaben dafür unter /api/user/self.",
    "Use {url}": "{url} verwenden",
    "A new-api relay also wants the header New-Api-User = your user ID (shown in the site's personal settings): add it under Headers.": "Ein new-api-Relay verlangt zusätzlich den Header New-Api-User = Ihre Benutzer-ID (in den persönlichen Einstellungen der Website zu sehen): Fügen Sie ihn unter „Header“ hinzu.",
    "The Balance URL …/api/usage/token takes the API key, not the access token — set it to …/api/user/self in the provider's settings": "Die Guthaben-URL …/api/usage/token erwartet den API-Schlüssel, nicht das Zugriffstoken – stellen Sie sie in den Anbietereinstellungen auf …/api/user/self",
    "Add the header New-Api-User = your user ID (shown in the site's personal settings) to the provider's Headers": "Fügen Sie den Header New-Api-User = Ihre Benutzer-ID (in den persönlichen Einstellungen der Website zu sehen) zu den Headern des Anbieters hinzu",
    "Check balance": "Guthaben prüfen",
    "Ask the Balance URL now, as the form has it": "Guthaben-URL jetzt mit den Formularwerten abfragen",
    "No Balance URL to ask": "Keine Guthaben-URL zum Abfragen",
    "A key tells only what is left on itself. For the whole account's balance on the Usage page, generate a System Access Token in {p}'s settings and paste it here; it is used for nothing else.": "Ein Schlüssel liefert nur sein eigenes Restguthaben. Für das Guthaben des gesamten Kontos auf der Seite „Nutzung“ erzeugen Sie in den Einstellungen von {p} ein System Access Token und fügen es hier ein; es wird für nichts anderes verwendet.",
