    "the gateway stayed busy for an hour, so magpie didn't restart; it updates when you restart or quit it": "Der Zugangspunkt war eine Stunde lang ausgelastet, daher hat magpie nicht neu gestartet; das Update erfolgt beim nächsten Neustart oder Beenden",
