    "Updates are downloaded from GitHub; a mirror can be used where GitHub is slow": "Updates werden von GitHub geladen; wo GitHub langsam ist, hilft ein Spiegel",
    "The update and its checksum always come from usemagpie.ai; a file from the mirror that doesn't match it is not installed.": "Update und Prüfsumme kommen immer von usemagpie.ai; eine Datei vom Spiegel, die nicht passt, wird nicht installiert.",
