    "Puts {dir} first in your user PATH and writes magpie.cmd there, which runs {name}": "Setzt {dir} an den Anfang Ihres Benutzer-PATH und legt dort eine magpie.cmd ab, die {name} startet",
    "Added: magpie.cmd beside {name} runs it as magpie; open a new PowerShell or Command Prompt window to run magpie": "Hinzugefügt: Die magpie.cmd neben {name} startet es als magpie. Öffnen Sie ein neues PowerShell- oder Eingabeaufforderungsfenster, um magpie auszuführen",
    "which runs {name}": "startet {name}",
    "Puts {dir} first in your user PATH": "Setzt {dir} an den Anfang Ihres Benutzer-PATH",
