    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there first": "macOS führt magpie aus einer temporären Kopie aus, bis es in Programme verschoben ist: verschieben Sie es zuerst dorthin",
    "magpie runs from its disk image: copy it to Applications first": "magpie läuft aus seinem Disk-Image: kopieren Sie es zuerst in Programme",
