    "PowerShell and cmd take up a change in new windows; restart Windows Terminal if it is open": "PowerShell und cmd übernehmen eine Änderung in neuen Fenstern; starten Sie Windows Terminal neu, falls es offen ist",
    "A change reaches terminals opened after it": "Eine Änderung gilt für danach geöffnete Terminals",
