    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there, open it again, then add the command": "macOS führt magpie aus einer temporären Kopie aus, bis es in Programme verschoben ist: verschieben Sie es, öffnen Sie es erneut und fügen Sie dann den Befehl hinzu",
    "magpie is running from its disk image: copy it to Applications, open it from there, then add the command": "magpie läuft aus seinem Disk-Image: kopieren Sie es in Programme, öffnen Sie es von dort und fügen Sie dann den Befehl hinzu",
    "no folder on your PATH can take the magpie command: add ~/.local/bin to a shell's profile below": "Kein Ordner im PATH kann den magpie-Befehl aufnehmen: fügen Sie unten ~/.local/bin dem Profil einer Shell hinzu",
