    "Counted from magpie's readings of the vendor's meter, since {date}: what is used while magpie isn't reading it is counted on the day it next does": "Seit {date} aus den Ablesungen von magpie am Zähler des Anbieters gezählt: Was verbraucht wird, während magpie nicht abliest, zählt für den Tag der nächsten Ablesung",
