    "Counted since {date}": "Gezählt seit {date}",
    "Accounts hidden": "Konten verborgen",
    "Accounts are masked for a screenshot — click to show them": "Konten sind für einen Screenshot maskiert – zum Anzeigen klicken",
    "Add a model": "Modell hinzufügen",
    "Add another model": "Weiteres Modell hinzufügen",
    "Patterns": "Muster",
