    "Speed": "Tempo",
    "Output speed": "Ausgabetempo",
    "first token in {ms} on average": "erstes Token im Schnitt nach {ms}",
    "no streamed replies timed": "keine gestreamte Antwort gemessen",
    "Output tokens a second after the first, over the streamed replies": "Ausgabe-Token pro Sekunde nach dem ersten, über die gestreamten Antworten",
    "No streamed replies timed in this period": "In diesem Zeitraum wurde keine gestreamte Antwort gemessen",
    "Sent, Effort and the cache are in each row's details": "Schmales Fenster: Gesendet, Effort und Cache stehen in den Details jeder Zeile",
    "{n} output tokens in {ms} after the first": "{n} Ausgabe-Token in {ms} nach dem ersten",
    "Not streamed: no first token to time a speed from": "Nicht gestreamt: kein erstes Token, an dem sich ein Tempo messen ließe",
    "Cache": "Cache",
