    "It is taken out of every agent it was given to. The folder it was linked from stays where it is.": "Er wird aus jedem Agenten entfernt, dem er gegeben wurde. Der Ordner, aus dem er verlinkt war, bleibt, wo er ist.",
    "It is taken out of every agent it was given to, and its folder is moved to magpie's backups.": "Er wird aus jedem Agenten entfernt, dem er gegeben wurde, und sein Ordner wird in die Backups von magpie verschoben.",
